; ChipOS - built-in apps: CALC (6), NOTEPAD (7), STOPWATCH (8), TIMER (9),
; COUNTDOWN (10). They draw App Kit frames (same look as add-on apps) that
; ChipOS renders itself. An add-on drive with the same app is ignored.
var $bk_frame = ""
var $ba_cur = 6                         ; open built-in app

function @bk_begin()
	$bk_frame = ""

function @bk_add($el : text)
	if $bk_frame != ""
		$bk_frame = $bk_frame & "|"
	$bk_frame = $bk_frame & $el

function @bk_text($x : number, $y : number, $size : number, $color : text, $t : text)
	@bk_add(text("T~{}~{}~{}~{}~", $x, $y, $size, $color) & $t)

function @bk_text_c($x : number, $y : number, $size : number, $color : text, $t : text)
	@bk_add(text("C~{}~{}~{}~{}~", $x, $y, $size, $color) & $t)

function @bk_button($id : text, $x : number, $y : number, $w : number, $h : number, $label : text)
	@bk_add(text("B~{}~{}~{}~{}~", $x, $y, $w, $h) & $id & "~" & $label)

function @bk_box($x : number, $y : number, $w : number, $h : number, $color : text)
	@bk_add(text("R~{}~{}~{}~{}~", $x, $y, $w, $h) & $color)

function @bk_bar($x : number, $y : number, $w : number, $h : number, $pct : number, $color : text)
	@bk_add(text("G~{}~{}~{}~{}~{}~", $x, $y, $w, $h, $pct) & $color)

function @bk_para($x : number, $y : number, $w : number, $size : number, $color : text, $t : text)
	@bk_add(text("P~{}~{}~{}~{}~{}~", $x, $y, $w, $size, $color) & $t)

; Keep typed text from breaking a frame.
function @bk_clean($t : text) : text
	return replace(replace(replace(replace($t, "|", "/"), "~", "-"), "{", "("), "}", ")")

function @two($n : number) : text
	if $n < 10
		return text("0{}", $n)
	return text("{}", $n)

; ================= CALC =================
var $ca_disp = "0"
var $ca_acc = 0
var $ca_op = ""
var $ca_fresh = 1
var $ca_deg = 1
var $ca_mem = 0
var $ca_hist = ""
array $ca_bl : text
array $ca_wl : text

function @ca_init()
	$ca_wl.clear()
	$ca_wl.append("7", "8", "9", "/")
	$ca_wl.append("4", "5", "6", "*")
	$ca_wl.append("1", "2", "3", "-")
	$ca_wl.append("C", "0", "=", "+")
	$ca_bl.clear()
	$ca_bl.append("DEG", "MC", "MR", "M+", "C")
	$ca_bl.append("sin", "cos", "tan", "pi", "DEL")
	$ca_bl.append("x2", "sqrt", "x^y", "1/x", "/")
	$ca_bl.append("7", "8", "9", "*", "log")
	$ca_bl.append("4", "5", "6", "-", "ln")
	$ca_bl.append("1", "2", "3", "+", "e")
	$ca_bl.append("+/-", "0", ".", "=", "%")

function @ca_val() : number
	if isnumeric($ca_disp)
		return $ca_disp:number
	return 0

function @ca_show($v : number)
	if ($v != $v) or (abs($v) > 1000000000000000)
		$ca_disp = "ERROR"
	else
		$ca_disp = text("{}", round($v * 1000000000) / 1000000000)
	$ca_fresh = 1

function @ca_apply()
	var $b = @ca_val()
	var $r = $b
	if $ca_op == "+"
		$r = $ca_acc + $b
	elseif $ca_op == "-"
		$r = $ca_acc - $b
	elseif $ca_op == "*"
		$r = $ca_acc * $b
	elseif $ca_op == "/"
		if $b == 0
			$r = 0 / 0
		else
			$r = $ca_acc / $b
	elseif $ca_op == "^"
		$r = pow($ca_acc, $b)
	if $ca_op != ""
		$ca_hist = text("{} {} {} =", $ca_acc, $ca_op, $b)
	$ca_op = ""
	@ca_show($r)

function @ca_ang($v : number) : number
	if $ca_deg
		return $v * pi / 180
	return $v

function @ca_press($k : text)
	if (size($k) == 1) and (find("0123456789", $k) >= 0)
		if $ca_fresh or ($ca_disp == "0") or ($ca_disp == "ERROR")
			$ca_disp = $k
		else
			$ca_disp = $ca_disp & $k
		$ca_fresh = 0
	elseif $k == "."
		if $ca_fresh or ($ca_disp == "ERROR")
			$ca_disp = "0."
		elseif !contains($ca_disp, ".")
			$ca_disp = $ca_disp & "."
		$ca_fresh = 0
	elseif $k == "C"
		$ca_disp = "0"
		$ca_acc = 0
		$ca_op = ""
		$ca_hist = ""
		$ca_fresh = 1
	elseif $k == "DEL"
		if (!$ca_fresh) and (size($ca_disp) > 1)
			$ca_disp = substring($ca_disp, 0, size($ca_disp) - 1)
		else
			$ca_disp = "0"
			$ca_fresh = 1
	elseif ($k == "+") or ($k == "-") or ($k == "*") or ($k == "/") or ($k == "x^y")
		if ($ca_op != "") and (!$ca_fresh)
			@ca_apply()
		$ca_acc = @ca_val()
		$ca_op = $k
		if $k == "x^y"
			$ca_op = "^"
		$ca_hist = text("{} {}", $ca_acc, $ca_op)
		$ca_fresh = 1
	elseif $k == "="
		@ca_apply()
	elseif $k == "+/-"
		@ca_show(-@ca_val())
		$ca_fresh = 0
	elseif $k == "%"
		@ca_show(@ca_val() / 100)
	elseif $k == "x2"
		@ca_show(@ca_val() * @ca_val())
	elseif $k == "sqrt"
		@ca_show(sqrt(@ca_val()))
	elseif $k == "1/x"
		@ca_show(1 / @ca_val())
	elseif $k == "sin"
		@ca_show(sin(@ca_ang(@ca_val())))
	elseif $k == "cos"
		@ca_show(cos(@ca_ang(@ca_val())))
	elseif $k == "tan"
		@ca_show(tan(@ca_ang(@ca_val())))
	elseif $k == "log"
		@ca_show(log(@ca_val()))
	elseif $k == "ln"
		@ca_show(log(@ca_val(), 2.718281828459045))
	elseif $k == "pi"
		@ca_show(pi)
	elseif $k == "e"
		@ca_show(2.718281828459045)
	elseif $k == "DEG"
		$ca_deg = !$ca_deg
	elseif $k == "MC"
		$ca_mem = 0
	elseif $k == "MR"
		@ca_show($ca_mem)
	elseif $k == "M+"
		$ca_mem += @ca_val()
		$ca_fresh = 1

function @ca_frame()
	@bk_box(4, 1, 92, 22, "panel")
	var $mode = "RAD"
	if $ca_deg
		$mode = "DEG"
	var $top = $mode
	if $ca_mem != 0
		$top = $mode & "   M"
	@bk_text(6, 3, 1, "dim", $top)
	@bk_text(30, 3, 1, "dim", $ca_hist)
	@bk_text_c(50, 9, 3, "text", $ca_disp)
	repeat 35 ($i)
		var $c = mod($i, 5)
		var $r = floor($i / 5)
		var $lab = $ca_bl.$i
		if ($lab == "DEG") and (!$ca_deg)
			$lab = "RAD"
		@bk_button($ca_bl.$i, 4 + $c * 18.6, 26 + $r * 10.6, 17.4, 9.6, $lab)

function @ca_widget()
	@bk_box(3, 2, 94, 18, "panel")
	@bk_text_c(50, 5, 1.6, "text", $ca_disp)
	repeat 16 ($wi)
		var $wc = mod($wi, 4)
		var $wr = floor($wi / 4)
		@bk_button($ca_wl.$wi, 3 + $wc * 24, 23 + $wr * 19.2, 22.5, 17.6, $ca_wl.$wi)

; ================= NOTEPAD =================
storage array $bn_notes : text
storage var $bn_pin : number            ; note on the sticky widget (+1; 0 = newest)
var $bn_view = -1
var $bn_page = 0

function @bn_sticky() : number
	var $p = $bn_pin - 1
	if ($p >= 0) and ($p < $bn_notes.size)
		return $p
	return $bn_notes.size - 1

function @bn_tap($t : text)
	if $t == "new"
		@kb_open(-2, "ba_new", "NEW NOTE", "")
	elseif $t == "back"
		$bn_view = -1
	elseif $t == "edit"
		if ($bn_view >= 0) and ($bn_view < $bn_notes.size)
			@kb_open(-2, "ba_edit", "EDIT NOTE", $bn_notes.$bn_view)
	elseif $t == "pin"
		if $bn_pin == $bn_view + 1
			$bn_pin = 0
		else
			$bn_pin = $bn_view + 1
	elseif $t == "del"
		if ($bn_view >= 0) and ($bn_view < $bn_notes.size)
			$bn_notes.erase($bn_view)
			if $bn_pin == $bn_view + 1
				$bn_pin = 0
			elseif $bn_pin > $bn_view + 1
				$bn_pin -= 1
		$bn_view = -1
		$bn_page = 0
	elseif $t == "prev"
		$bn_page = max($bn_page - 1, 0)
	elseif $t == "next"
		$bn_page += 1
	elseif substring($t, 0, 2) == "n_"
		var $nt = substring($t, 2, 6)
		var $ni = $nt:number
		if $ni < $bn_notes.size
			$bn_view = $ni

function @bn_frame()
	if ($bn_view < 0) or ($bn_view >= $bn_notes.size)
		$bn_view = -1
		var $n = $bn_notes.size
		@bk_text(5, 3, 2, "accent", text("NOTES ({})", $n))
		@bk_button("new", 70, 2, 25, 10, "+ NEW")
		var $pages = max(ceil($n / 7), 1)
		$bn_page = min($bn_page, $pages - 1)
		if $n == 0
			@bk_text_c(50, 45, 1.5, "dim", "No notes yet. Tap + NEW.")
		repeat 7 ($r)
			var $i = $bn_page * 7 + $r
			if $i < $n
				var $first = $bn_notes.$i
				if size($first) > 60
					$first = substring($first, 0, 58) & ".."
				@bk_button(text("n_{}", $i), 5, 15 + $r * 10.5, 90, 9.5, $first)
		if $pages > 1
			@bk_button("prev", 5, 90, 20, 8, "< PREV")
			@bk_text_c(50, 92, 1, "dim", text("PAGE {} / {}", $bn_page + 1, $pages))
			@bk_button("next", 75, 90, 20, 8, "NEXT >")
	else
		@bk_text(5, 3, 2, "accent", text("NOTE {}", $bn_view + 1))
		@bk_box(4, 14, 92, 64, "panel")
		@bk_para(6, 16, 88, 1.4, "text", $bn_notes.$bn_view)
		@bk_button("back", 4, 82, 22, 12, "< BACK")
		@bk_button("edit", 28, 82, 21, 12, "EDIT")
		var $pl = "PIN"
		if $bn_pin == $bn_view + 1
			$pl = "UNPIN"
		@bk_button("pin", 51, 82, 21, 12, $pl)
		@bk_button("del", 74, 82, 22, 12, "DELETE")

; widget 0 sticky note, 1 note list
function @bn_widget($n : number)
	if $n == 0
		var $sn = @bn_sticky()
		@bk_box(3, 3, 94, 94, "#e8c840")
		if $sn >= 0
			var $st = $bn_notes.$sn
			if size($st) > 160
				$st = substring($st, 0, 158) & ".."
			@bk_para(7, 7, 86, 1.2, "#2a2410", $st)
			@bk_button(text("open:n_{}", $sn), 58, 80, 36, 14, "OPEN")
		else
			@bk_text_c(50, 40, 1.2, "#2a2410", "NO NOTES")
			@bk_button("open:new", 30, 70, 40, 16, "+ NEW")
		return
	var $wn = $bn_notes.size
	@bk_text(5, 4, 1.2, "accent", text("NOTES ({})", $wn))
	@bk_button("open:new", 66, 2, 30, 14, "+ NEW")
	var $ws = min($wn, 4)
	repeat $ws ($wr)
		var $wi = $wn - 1 - $wr
		var $wt = $bn_notes.$wi
		if size($wt) > 40
			$wt = substring($wt, 0, 38) & ".."
		@bk_button(text("open:n_{}", $wi), 4, 20 + $wr * 19.5, 92, 17.5, $wt)
	if $wn == 0
		@bk_text_c(50, 50, 1, "dim", "No notes yet")

; ================= STOPWATCH =================
var $sw_run = 0
var $sw_seen = -10                      ; a stopwatch widget was drawn (time)
var $sw_start = 0
var $sw_acc = 0
var $sw_last = 0
array $sw_laps : number

function @sw_elapsed() : number
	if $sw_run
		return $sw_acc + (time - $sw_start)
	return $sw_acc

function @sw_fmt($s : number) : text
	var $m = floor($s / 60)
	var $sec = floor(mod($s, 60))
	var $t = floor(mod($s * 10, 10))
	return @two($m) & ":" & @two($sec) & text(".{}", $t)

function @sw_tap($t : text)
	if $t == "go"
		if $sw_run
			$sw_acc = @sw_elapsed()
			$sw_run = 0
		else
			$sw_start = time
			$sw_run = 1
	elseif $t == "lap"
		if $sw_run
			var $now = @sw_elapsed()
			$sw_laps.append($now - $sw_last)
			$sw_last = $now
	elseif $t == "reset"
		if !$sw_run
			$sw_acc = 0
			$sw_last = 0
			$sw_laps.clear()

function @sw_frame()
	@bk_text_c(50, 6, 5, "text", @sw_fmt(@sw_elapsed()))
	var $gl = "START"
	if $sw_run
		$gl = "STOP"
	@bk_button("go", 6, 30, 28, 14, $gl)
	@bk_button("lap", 36, 30, 28, 14, "LAP")
	@bk_button("reset", 66, 30, 28, 14, "RESET")
	var $n = $sw_laps.size
	var $show = min($n, 7)
	repeat $show ($i)
		var $k = $n - 1 - $i
		@bk_text(20, 50 + $i * 6.5, 1.4, "dim", text("LAP {}", $k + 1))
		@bk_text(55, 50 + $i * 6.5, 1.4, "text", @sw_fmt($sw_laps.$k))

function @sw_widget()
	$sw_seen = time
	@bk_text_c(50, 8, 2, "text", @sw_fmt(@sw_elapsed()))
	var $wg = "START"
	if $sw_run
		$wg = "STOP"
	@bk_button("go", 6, 58, 42, 34, $wg)
	@bk_button("reset", 52, 58, 42, 34, "RESET")

; ================= TIMER =================
var $tmr_set = 300
var $tmr_left = 300
var $tmr_run = 0
var $tmr_end = 0
var $tmr_ring = 0
var $tmr_ring_next = 0

function @tmr_remaining() : number
	if $tmr_run
		return max($tmr_end - time, 0)
	return $tmr_left

function @tmr_tap($t : text)
	if (!$tmr_run) and (!$tmr_ring)
		if $t == "m+"
			$tmr_set = min($tmr_set + 60, 99 * 60)
		elseif $t == "m-"
			$tmr_set = max($tmr_set - 60, 0)
		elseif $t == "s+"
			$tmr_set = min($tmr_set + 5, 99 * 60 + 55)
		elseif $t == "s-"
			$tmr_set = max($tmr_set - 5, 0)
		if ($t == "m+") or ($t == "m-") or ($t == "s+") or ($t == "s-")
			$tmr_left = $tmr_set
	if $t == "go"
		if $tmr_ring
			$tmr_ring = 0
			$tmr_left = $tmr_set
		elseif $tmr_run
			$tmr_left = @tmr_remaining()
			$tmr_run = 0
		elseif $tmr_left > 0
			$tmr_end = time + $tmr_left
			$tmr_run = 1
	elseif $t == "reset"
		$tmr_run = 0
		$tmr_ring = 0
		$tmr_left = $tmr_set

function @tmr_frame()
	var $r = ceil(@tmr_remaining())
	var $tt = @two(floor($r / 60)) & ":" & @two(mod($r, 60))
	var $col = "text"
	if $tmr_ring
		$col = "bad"
	@bk_text_c(50, 6, 6, $col, $tt)
	var $pct = 0
	if $tmr_set > 0
		$pct = 100 - @tmr_remaining() / $tmr_set * 100
	@bk_bar(10, 34, 80, 5, $pct, "accent")
	@bk_button("m-", 10, 44, 18, 12, "- MIN")
	@bk_button("m+", 30, 44, 18, 12, "+ MIN")
	@bk_button("s-", 52, 44, 18, 12, "- 5 S")
	@bk_button("s+", 72, 44, 18, 12, "+ 5 S")
	var $gl = "START"
	if $tmr_run
		$gl = "PAUSE"
	if $tmr_ring
		$gl = "STOP ALARM"
	@bk_button("go", 10, 62, 38, 16, $gl)
	@bk_button("reset", 52, 62, 38, 16, "RESET")
	if $tmr_ring
		@bk_text_c(50, 84, 2, "bad", "TIME'S UP")

; ================= COUNTDOWN =================
storage var $cdn_name : text
storage var $cdn_target : number        ; unix time (UTC)
storage var $cdn_ver : number
var $cdn_beeped = 0

function @cdn_load()
	if $cdn_ver != 1
		$cdn_name = "LAUNCH"
		$cdn_target = floor(time / 3600) * 3600 + 86400
		$cdn_ver = 1

function @cdn_tap($t : text)
	if $t == "name"
		@kb_open(-2, "ba_name", "EVENT NAME", $cdn_name)
	elseif $t == "d+"
		$cdn_target += 86400
	elseif $t == "d-"
		$cdn_target -= 86400
	elseif $t == "h+"
		$cdn_target += 3600
	elseif $t == "h-"
		$cdn_target -= 3600
	elseif $t == "m+"
		$cdn_target += 300
	elseif $t == "m-"
		$cdn_target -= 300
	elseif $t == "now"
		$cdn_target = floor(time / 60) * 60 + 3600
	if $t != ""
		$cdn_beeped = time >= $cdn_target

function @cdn_frame()
	@bk_text_c(50, 3, 2.5, "accent", $cdn_name)
	var $l = $cdn_target - time
	var $l2 = max($l, 0)
	var $dd = floor($l2 / 86400)
	var $hh = floor(mod($l2, 86400) / 3600)
	var $mm = floor(mod($l2, 3600) / 60)
	var $ss = floor(mod($l2, 60))
	var $big = text("{}d ", $dd) & @two($hh) & ":" & @two($mm) & ":" & @two($ss)
	var $col = "text"
	if $l <= 0
		$big = "IT'S TIME!"
		$col = "ok"
	@bk_text_c(50, 18, 4.5, $col, $big)
	@clk_calc_at($cdn_target, -1, 0)
	var $tl = "TARGET: " & @fmt_date($cfg_datefmt) & "  " & @fmt_hm($ck_h, $ck_mi, $cfg_24h)
	@bk_text_c(50, 42, 1.5, "dim", $tl)
	@bk_button("d-", 6, 52, 13, 11, "- DAY")
	@bk_button("d+", 21, 52, 13, 11, "+ DAY")
	@bk_button("h-", 36, 52, 13, 11, "- HR")
	@bk_button("h+", 51, 52, 13, 11, "+ HR")
	@bk_button("m-", 66, 52, 13, 11, "- 5M")
	@bk_button("m+", 81, 52, 13, 11, "+ 5M")
	@bk_button("name", 6, 68, 42, 13, "RENAME")
	@bk_button("now", 52, 68, 42, 13, "1 HOUR FROM NOW")
	@bk_text_c(50, 88, 1, "dim", "NOW: " & @clk_date() & "  " & @clk_text())

; ================= shared =================
function @ba_init()
	@ca_init()
	@cdn_load()
	$cdn_beeped = time >= $cdn_target

; Tap on a built-in app's button ("open:..." = from a widget: open the app).
function @ba_tap($a : number, $k0 : text)
	var $k = $k0
	if find($k, "open:") == 0
		$k = substring($k, 5, size($k))
		$ba_cur = $a
		@go("bapp")
	if $a == 6
		@ca_press($k)
	elseif $a == 7
		@bn_tap($k)
	elseif $a == 8
		@sw_tap($k)
	elseif $a == 9
		@tmr_tap($k)
	else
		@cdn_tap($k)
	$ui_dirty = 1

function @ba_clear($a : number)
	if $a == 6
		@ca_press("C")
		$ca_mem = 0
	elseif $a == 7
		$bn_notes.clear()
		$bn_pin = 0
		$bn_view = -1
		$bn_page = 0
	elseif $a == 8
		$sw_run = 0
		$sw_acc = 0
		$sw_last = 0
		$sw_laps.clear()
	elseif $a == 9
		$tmr_run = 0
		$tmr_ring = 0
		$tmr_set = 300
		$tmr_left = 300
	else
		$cdn_ver = 0
		@cdn_load()

; Keyboard result for a built-in app.
function @ba_kb_done($id : text, $ok : number, $t0 : text)
	var $t = @bk_clean($t0)
	if $id == "ba_new"
		if $ok and ($t != "")
			$bn_notes.append($t)
			$bn_view = -1
	elseif $id == "ba_edit"
		if $ok and ($bn_view >= 0) and ($bn_view < $bn_notes.size)
			$bn_notes.$bn_view = $t
	elseif $id == "ba_name"
		if $ok and ($t != "")
			$cdn_name = upper($t)
	$ui_dirty = 1

; Draw a built-in app's frame into an area; $wn = -1 the app, else widget n.
function @ba_draw($a : number, $wn : number, $x : number, $y : number, $w : number, $h : number)
	@bk_begin()
	if $a == 6
		if $wn < 0
			@ca_frame()
		else
			@ca_widget()
	elseif $a == 7
		if $wn < 0
			@bn_frame()
		else
			@bn_widget($wn)
	elseif $a == 8
		if $wn < 0
			@sw_frame()
		else
			@sw_widget()
	elseif $a == 9
		@tmr_frame()
	else
		@cdn_frame()
	@xf_render($bk_frame, $x, $y, $w, $h, -10 - $a)

function @page_bapp()
	@ba_draw($ba_cur, -1, $content_x, $content_y, $content_w, $content_h)

; Every tick: alarms and live redraws.
var $ba_draw_next = 0
function @ba_tick()
	if $tmr_run and (@tmr_remaining() <= 0)
		$tmr_run = 0
		$tmr_left = 0
		$tmr_ring = 1
		$tmr_ring_next = 0
		@notify("TIMER: TIME'S UP")
	if $tmr_ring and (time >= $tmr_ring_next)
		$tmr_ring_next = time + 1
		@snd_beep(1046, 0.4)
		$ui_dirty = 1
	if (!$cdn_beeped) and (time >= $cdn_target)
		$cdn_beeped = 1
		@snd_beep(880, 0.6)
		@notify("COUNTDOWN: " & $cdn_name & " - IT'S TIME!")
	; keep running clocks moving on screen
	if time >= $ba_draw_next
		var $live = 0
		if $ui_page == "bapp"
			if ($ba_cur == 8) and $sw_run
				$live = 0.1
			elseif ($ba_cur == 9) and $tmr_run
				$live = 0.25
			elseif $ba_cur == 10
				$live = 0.5
		if ($live == 0) and $sw_run and (time - $sw_seen < 2)
			$live = 0.2
		if $live > 0
			$ba_draw_next = time + $live
			$ui_dirty = 1
		else
			$ba_draw_next = time + 0.2

; ChipOS - on-screen QWERTY keyboard. Any app can ask for text input
; (App Kit @kit_input); a named physical Keyboard can be used as well.
; Not typeable: | ~ { } (protocol characters) and the double quote.
array $kb_lab : text
array $kb_sh : text
array $kb_w : number
array $kb_row : number
