function @kb_open($app : number, $id : text, $prompt : text, $init : text)
	$kb_on = 1
	$kb_app = $app
	$kb_id = $id
	$kb_prompt = $prompt
	$kb_text = $init
	$kb_shift = 0
	$ui_dirty = 1

; Send the result to the app and close.
function @kb_finish($cancel : number)
	$kb_on = 0
	$ui_dirty = 1
	if $kb_app == -2
		$kb_int_text = $kb_text
		$kb_int_done = 1 + $cancel
		return
	if ($kb_app < 0) or ($kb_app >= $xa_alias.size)
		return
	var $t = $kb_text
	$t = replace($t, "{", "(")
	$t = replace($t, "}", ")")
	$t = replace($t, "|", "/")
	$t = replace($t, "~", "-")
	var $save_cur = $xa_cur
	$xa_cur = $kb_app
	var $fc = @clk_text()
	var $fd = @clk_day()
	if $cancel
		@xa_send("input_cancel", $kb_id, $fc, $fd, $cfg_units, "")
	else
		@xa_send("input", $kb_id, $fc, $fd, $cfg_units, ".text{" & $t & "}")
	$xa_cur = $save_cur

function @kb_upper() : number
	return ($kb_shift + $kb_caps) == 1

function @kb_press($i : number)
	var $a = $kb_act.$i
	if $a == "c"
		var $ch = $kb_lab.$i
		if @kb_upper()
			$ch = $kb_sh.$i
			if $ch == "DQ"
				$ch = "'"
		if size($kb_text) < 400
			$kb_text = $kb_text & $ch
		$kb_shift = 0
	elseif $a == "space"
		$kb_text = $kb_text & " "
	elseif $a == "tab"
		$kb_text = $kb_text & "  "
	elseif $a == "bk"
		if size($kb_text) > 0
			$kb_text = substring($kb_text, 0, size($kb_text) - 1)
	elseif $a == "clear"
		$kb_text = ""
	elseif $a == "shift"
		$kb_shift = !$kb_shift
	elseif $a == "caps"
		$kb_caps = !$kb_caps
	elseif $a == "done"
		@kb_finish(0)
	elseif $a == "cancel"
		@kb_finish(1)
	$ui_dirty = 1

; Physical keyboard: mirror its text (ch0, assumed) and submit on confirm (ch1).
function @kb_tick()
	if !$kb_on
		return
	if $kb_phys == ""
		var $pn = $db_id.size
		repeat $pn ($pj)
			if ($kb_phys == "") and contains($db_type.$pj, "Keyboard") and ($db_alias.$pj != "") and ($db_seen.$pj >= $scan_gen - 1)
				$kb_phys = $db_alias.$pj
				$kb_phys_last = @in_t($kb_phys, 0)
	if $kb_phys == ""
		return
	var $pt = @in_t($kb_phys, 0)
	if $pt != $kb_phys_last
		$kb_phys_last = $pt
		$kb_text = $pt
		$ui_dirty = 1
	if @in_n($kb_phys, 1) == 1
		$kb_text = $pt
		@kb_finish(0)

; A keycap: dark edge, raised face, legend (+ small shifted legend).
function @kb_cap($x : number, $y : number, $w : number, $h : number, $lab : text, $sh : text, $mod : number, $lit : number)
	var $edge = color(10, 12, 16)
	var $face = color(52, 58, 68)
	var $top = color(68, 76, 88)
	var $ink = color(235, 238, 242)
	if $mod
		$face = color(36, 41, 49)
		$top = color(48, 54, 64)
		$ink = color(170, 180, 192)
	if $lit
		$face = $th_accent_dk
		$top = $th_accent
		$ink = color(8, 12, 18)
	@ui_box($x, $y, $w, $h, $face, $edge)
	@ui_box($x + 2, $y + 2, $w - 4, $h * 0.72, $top, $top)
	var $small = $h < $chh * 2.8
	if $small
		; compact: one legend per key, short names for wide keys
		var $sl = $lab
		if size($sl) * $cw > $w - $cw * 0.5
			if $lab == "BACKSPACE"
				$sl = "<X"
			elseif $lab == "CANCEL"
				$sl = "ESC"
			elseif $lab == "CLEAR"
				$sl = "CLR"
			elseif $lab == "ENTER"
				$sl = "ENT"
			elseif $lab == "SHIFT"
				$sl = "SHF"
			else
				$sl = @ui_fit($lab, floor($w / $cw))
		if (size($lab) == 1) and ($sh == upper($lab))
			$sl = upper($lab)
		@ui_text_c($x + $w / 2, $y + ($h * 0.72 - $chh) / 2 + 1, $ink, $sl)
		return
	if $sh == "DQ"
		; drawn double quote (cannot be typed in XenonCode text)
		@d_line($x + $cw * 0.5, $y + $chh * 0.3, $x + $cw * 0.5, $y + $chh * 0.8, $ink)
		@d_line($x + $cw * 0.9, $y + $chh * 0.3, $x + $cw * 0.9, $y + $chh * 0.8, $ink)
	elseif ($sh != "") and ($sh != $lab) and (size($lab) == 1) and ($sh != upper($lab))
		@ui_text($x + $cw * 0.4, $y + $chh * 0.2, $ink, $sh)
	var $lb = $lab
	if (size($lab) == 1) and ($sh == upper($lab))
		$lb = upper($lab)
	var $ly = $y + ($h * 0.72 - $chh) / 2 + 1
	if ($sh != "") and ($sh != upper($lab)) and (size($lab) == 1)
		$ly = $y + $h * 0.72 - $chh - 1
	@ui_text_c($x + $w / 2, $ly, $ink, $lb)

function @kb_draw()
	@ui_hit(0, 0, $desk_w, $desk_h, "")
	var $kw = min($desk_w - $cw * 2, $cw * 15 * 7)
	var $u = $kw / 15
	var $kh = min($u * 0.92, ($desk_h - $sb_h) * 0.11)
	var $gap = max($u * 0.06, 2)
	var $field_h = $chh * 3.4
	var $kx = $desk_w / 2 - $kw / 2
	; Lay out bottom-up estimate, then top-down with screen-edge snapping.
	var $est = $field_h + $kh * 5 + $gap * 6 + $chh * 2
	var $ky = max($sb_h + $chh, $desk_h - $nb_h - $est - $kh)
	array $kb_ry : number
	$kb_ry.clear()
	var $fy0 = @bz_fit($ky + $chh * 0.3, $chh * 3)
	var $yy = $fy0 + $field_h - $chh * 0.3
	repeat 5 ($rr)
		$yy = @bz_fit($yy, $kh)
		$kb_ry.append($yy)
		$yy += $kh + $gap
	var $bot = $yy + $chh * 0.4
	; board
	@ui_box($kx - $cw * 0.6, $ky, $kw + $cw * 1.2, $bot - $ky, color(22, 25, 31), $th_line)
	; text field
	@ui_text($kx, $fy0, $th_dim, $kb_prompt)
	var $fy = $fy0 + $chh * 1.1
	@ui_box($kx, $fy, $kw, $chh * 1.7, $th_bg, $th_accent)
	var $maxc = floor(($kw - $cw * 2) / $cw)
	var $shown = $kb_text
	if size($shown) > $maxc - 1
		$shown = substring($shown, size($shown) - $maxc + 1, $maxc - 1)
	var $cur = "_"
	if mod(time, 1) >= 0.5
		$cur = " "
	@ui_text($kx + $cw * 0.6, $fy + $chh * 0.35, $th_text, $shown & $cur)
	if $kb_phys != ""
		@ui_text_r($kx + $kw, $fy0, $th_dim, "KEYBOARD: " & $kb_phys)
	; keys
	var $rx = $kx
	var $cur_row = -1
	var $ry = 0
	var $kn = $kb_lab.size
	repeat $kn ($ki)
		var $r = $kb_row.$ki
		if $r != $cur_row
			$cur_row = $r
			$rx = $kx
			$ry = $kb_ry.$r
		var $w = $kb_w.$ki * $u
		var $a = $kb_act.$ki
		var $mod = ($a != "c") and ($a != "space")
		var $lit = 0
		if ($a == "shift") and $kb_shift
			$lit = 1
		if ($a == "caps") and $kb_caps
			$lit = 1
		if $a == "done"
			$lit = ($kb_lab.$ki == "DONE")
		var $lab = $kb_lab.$ki
		if ($a == "c") and @kb_upper() and (size($lab) == 1) and ($kb_sh.$ki == upper($lab))
			$lab = upper($lab)
		@kb_cap($rx + $gap / 2, $ry, $w - $gap, $kh, $lab, $kb_sh.$ki, $mod, $lit)
		$ui_hv = $ki
		@ui_hit($rx + $gap / 2, $ry, $rx + $w - $gap / 2, $ry + $kh, "kb")
		$rx += $w

; ChipOS - other screens: each can show the status panel, an app, a widget
; (incl. the attitude display) or nothing. Press and hold on the screen to
; choose; also from Settings > Display > OTHER SCREENS.
array $pjr_kind : number                ; picker rows
array $pjr_ref : number
array $pjr_box : text                   ; container rows (alias)

; The container-contents widget for a container (-1 none).
function @cw_find_box($a : text) : number
	var $n = $cw_type.size
	repeat $n ($i)
		if ($cw_type.$i == 9) and ($cw_src.$i == "box:" & $a)
			return $i
	return -1
var $pj_target = -1                     ; slot being set up from Settings
var $pj_keep_next = 0
array $pj_slots : number                ; OTHER SCREENS list rows -> slot

function @pjr_add($label : text, $kind : number, $ref : number)
	$sl_txt.append($label)
	$pjr_kind.append($kind)
	$pjr_ref.append($ref)

; Everything a screen can show -> $sl_txt / $pjr_kind / $pjr_ref.
function @pj_rows()
	$sl_txt.clear()
	$sl_spec.clear()
	$pjr_kind.clear()
	$pjr_ref.clear()
	@pjr_add("STATUS PANEL", 0, 0)
	@pjr_add("ATTITUDE DISPLAY", 2, 6)
	@pjr_add("COMPASS", 2, 7)
	@pjr_add("SPEEDOMETER", 2, 8)
	if $dv_present
		@pjr_add("DRIVE DISPLAY", 2, 9)
		@pjr_add("APP: DRIVE", 1, 5)
	if $cm_present
		@pjr_add("APP: COMMS", 1, 11)
		@pjr_add("APP: CONTACTS", 1, 13)
		@pjr_add("APP: SCANNER", 1, 14)
	if $cr_present
		@pjr_add("APP: CRAFT", 1, 12)
	if $sx_app
		@pjr_add("APP: SORTER", 1, 24)
	if $ws_present
		@pjr_add("APP: WEATHER", 1, 15)
		@pjr_add("WEATHER", 2, 14)
	if $so_present
		@pjr_add("APP: SOLAR", 1, 16)
	if $fl_app
		@pjr_add("APP: FLUIDS", 1, 17)
	if $rf_app
		@pjr_add("APP: REFINERY", 1, 18)
	if $lt_app
		@pjr_add("APP: LIGHTS", 1, 19)
	if $mn_app
		@pjr_add("APP: MINING", 1, 22)
	if $fy_app or $bt_app
		@pjr_add("ENGINES", 2, 15)
	if $fy_app
		@pjr_add("APP: FLY", 1, 20)
	if $bt_app
		@pjr_add("APP: BOAT", 1, 21)
	repeat 5 ($bq)
		@pjr_add("APP: " & @ba_name(6 + $bq), 1, 6 + $bq)
	repeat 4 ($bw)
		@pjr_add("WIDGET: " & @wg_name(10 + $bw), 2, 10 + $bw)
	@pjr_add("APP: POWER", 1, 1)
	@pjr_add("APP: CLOCK", 1, 4)
	@pjr_add("APP: DEVICES", 1, 2)
	var $xn = $xa_alias.size
	repeat $xn ($xk)
		if @xa_is_online($xk)
			@pjr_add("APP: " & $xa_name.$xk, 1, 100 + $xk)
	repeat 5 ($wk)
		var $wid = $wk + 1
		@pjr_add("WIDGET: " & @wg_name($wid), 2, $wid)
	; custom widgets that are on a home page
	var $hn = $hm_pg.size
	repeat $hn ($hi)
		if $hm_kind.$hi == 3
			var $cr = $hm_ref.$hi
			@pjr_add("WIDGET: " & $cw_name.$cr, 3, $cr)
	; v0.27: every container's contents, on any screen
	$pjr_box.clear()
	var $dn = $db_id.size
	repeat $dn ($dj)
		var $da = $db_alias.$dj
		if ($da != "") and ($db_seen.$dj >= $scan_gen - 1)
			var $dt = $db_type.$dj
			if ($dt == "Container") or ($dt == "SmallContainer")
				var $ex = @cw_find_box($da)
				if $ex < 0
					$ex = 10000 + $pjr_box.size
				$pjr_box.append($da)
				@pjr_add("CONTAINER: " & $da, 3, $ex)
	repeat $xn ($xk2)
		if @xa_is_online($xk2) and ($xk2 < $xa_wdef.size)
			var $wd = $xa_wdef.$xk2
			var $wn = min(@split_count($wd, "|"), 4)
			repeat $wn ($wq)
				var $wnm = @split_part(@split_part($wd, "|", $wq), "~", 0)
				@pjr_add("WIDGET: " & $xa_name.$xk2 & " " & upper($wnm), 4, $xk2 * 10 + $wq)
	@pjr_add("BLANK (OFF)", 9, 0)

function @pj_label($kind : number, $ref : number) : text
	if $kind == 0
		return "STATUS PANEL"
	if $kind == 9
		return "BLANK"
	if $kind == 1
		return "APP: " & @app_name($ref)
	if $kind == 2
		if $ref == 6
			return "ATTITUDE DISPLAY"
		if $ref >= 7
			return @wg_name($ref)
		return "WIDGET: " & @wg_name($ref)
	if $kind == 3
		if $ref < $cw_name.size
			return "WIDGET: " & $cw_name.$ref
		return "WIDGET"
	var $wa = floor($ref / 10)
	if $wa < $xa_name.size
		return "WIDGET: " & $xa_name.$wa
	return "APP WIDGET"

; Show a choice on slot k (and wake an external app so it draws).
function @pj_assign($k : number, $kind : number, $ref : number)
	if ($kind == 3) and ($ref >= 10000)
		; a container with no widget yet: make one (not placed on a home page)
		var $bi = $ref - 10000
		if $bi >= $pjr_box.size
			return
		var $ba = $pjr_box.$bi
		$ref = @cw_find_box($ba)
		if $ref < 0
			$cw_type.append(9)
			$cw_src.append("box:" & $ba)
			$cw_name.append(upper($ba))
			$cw_w.append(2)
			$cw_h.append(2)
			$cw_st.append(0)
			@cw_pad()
			$ref = $cw_type.size - 1
	@pj_set($k, $kind, $ref)
	if ($kind == 1) and ($ref >= 100)
		var $c = @clk_text()
		var $d = @clk_day()
		@xa_send_to($ref - 100, "open", "", $c, $d, $cfg_units, "")
	$ui_dirty = 1

; Keep projected external apps drawing (an app only draws while "open").
function @pj_keepalive()
	if $jn_mode and ($ui_page != "pj_join")
		$jn_mode = 0
		$jn_tap.clear()
		$panels_dirty = 1
	if time < $pj_keep_next
		return
	$pj_keep_next = time + 20
	repeat $slot_n ($k)
		if ($sl_role.$k == 2) and (@pj_kind_of($k) == 1) and (@pj_ref_of($k) >= 100)
			var $xk = @pj_ref_of($k) - 100
			if @xa_is_online($xk)
				var $c = @clk_text()
				var $d = @clk_day()
				@xa_send_to($xk, "tick", "", $c, $d, $cfg_units, "")

function @pj_app_draw($id : number)
	if $id < 100
		if $id == 1
			@page_power()
		elseif $id == 2
			@page_devices()
		elseif $id == 4
			@page_clock()
		elseif $id == 5
			@page_drive()
		elseif $id == 11
			@page_comms()
		elseif $id == 12
			@page_craft()
		elseif $id == 24
			@page_sorter()
		elseif $id == 15
			@page_weather()
		elseif $id == 16
			@page_solar()
		elseif $id == 17
			@page_fluids()
		elseif $id == 18
			@page_refinery()
		elseif $id == 19
			@page_lights()
		elseif $id == 20
			@page_fly()
		elseif $id == 21
			@page_boat()
		elseif $id == 22
			@page_mining()
		elseif $id == 13
			@page_cm_dir()
		elseif $id == 14
			@page_cm_scan()
		elseif ($id >= 6) and ($id <= 10)
			@ba_draw($id, -1, $content_x, $content_y, $content_w, $content_h)
		else
			@page_settings()
		return
	var $xk = $id - 100
	if !@xa_is_online($xk)
		@text_fit_c($content_x + $content_w / 2, $content_y + $content_h / 2 - $chh, $th_bad, "APP OFFLINE", $content_w)
		return
	var $fr = @in_t($xa_alias.$xk, 1)
	if $fr == ""
		@text_fit_c($content_x + $content_w / 2, $content_y + $content_h / 2 - $chh, $th_dim, $xa_name.$xk & "...", $content_w)
		return
	@xf_render($fr, $content_x, $content_y, $content_w, $content_h, $xk)

; Joining: each other screen shows its place in the order, or TAP TO ADD.
function @jn_tag_draw($k : number)
	var $w = $sl_w.$k
	var $h = $sl_h.$k
	var $pos = -1
	var $n = $jn_tap.size
	repeat $n ($q)
		if $jn_tap.$q == $k
			$pos = $q
	var $bg = $th_panel
	var $ink = $th_text
	if $pos >= 0
		$bg = $th_ok_dk
		$ink = $th_ok
	@ui_box(2, 2, $w - 4, $h - 4, $bg, $ink)
	if $pos >= 0
		var $nt = text("{}", $pos + 1)
		var $m = @fit_mul(2, $w * 0.5, $h * 0.5, 12)
		@ui_text_big($w / 2, $h / 2 - $chh * $m / 2, $ink, $nt, $m)
	else
		@text_fit_c($w / 2, $h / 2 - $chh * 1.5, $ink, "TAP TO ADD", $w - $cw * 2)
		@text_fit_c($w / 2, $h / 2, $th_dim, "TO THE BIG SCREEN", $w - $cw * 2)
	@text_fit_c($w / 2, $h - $chh * 2, $th_dim, text("{} #{}", $sl_alias.$k, $sl_ch.$k), $w - $cw * 2)
	$ui_hv = 0
	@ui_hit(0, 0, $w, $h, "jn_tap")

; Draw projected slot k (its own little desktop, own tap areas). Screens
; joined into one share their leader's content, each drawing its part.
function @proj_draw($k : number)
	var $sv_dw = $desk_w
	var $sv_dh = $desk_h
	var $sv_mode = $disp_mode
	var $sv_sc = $sc_pos
	var $sv_hit = $hit_on
	var $sv_hsl = $hit_sl_cur
	var $lead = @jn_lead_of($k)
	$hit_sl_cur = $lead
	$desk_w = $sl_w.$k
	$desk_h = $sl_h.$k
	$ox = 0
	$oy = 0
	if (!$jn_mode) and ($k < $sl_jw.size)
		$desk_w = $sl_jw.$k
		$desk_h = $sl_jh.$k
		$ox = $sl_jdx.$k
		$oy = $sl_jdy.$k
		; one set of tap areas per join (the leader's pass)
		if $lead != $k
			$hit_on = 0
	if $jn_mode
		$hit_sl_cur = $k
	$disp_mode = 0
	$cur_w = min($sl_w.$k, $rt_w)
	$cur_h = min($sl_h.$k, $rt_h)
	$rt.blank($th_bg)
	@ui_metrics()
	$content_x = $cw * 0.6
	$content_y = $chh * 0.6
	$content_w = $desk_w - $cw * 1.2
	$content_h = $desk_h - $chh * 1.2
	if $jn_mode
		@jn_tag_draw($k)
	elseif $pj_pick == $lead
		$sc_pos = $pj_sc
		@pj_rows()
		$pl_sel = -1
		var $cur_kind = @pj_kind_of($k)
		var $cur_ref = @pj_ref_of($k)
		var $rn = $pjr_kind.size
		repeat $rn ($ri)
			if ($pjr_kind.$ri == $cur_kind) and ($pjr_ref.$ri == $cur_ref)
				$pl_sel = $ri
		var $bw = $cw * 10
		@ui_btn($content_x + $content_w - $bw, $content_y - $chh * 0.3, $bw, $chh * 2, "CANCEL", "pj_cancel", 0)
		@pick_list("SHOW ON THIS SCREEN", "", "pj_pick")
		$pj_sc = $sc_pos
	else
		var $kind = @pj_kind_of($k)
		var $ref = @pj_ref_of($k)
		if $kind == 1
			@pj_app_draw($ref)
		elseif $kind == 2
			@wg_draw($ref, 0, 0, $desk_w, $desk_h, -1)
		elseif $kind == 3
			if $ref < $cw_type.size
				$bx_proj = 1
				@cw_draw($ref, 0, 0, $desk_w, $desk_h)
				$bx_proj = 0
		elseif $kind == 4
			var $wa = floor($ref / 10)
			var $wi = $ref - $wa * 10
			if @xa_is_online($wa)
				var $wf = @in_t($xa_alias.$wa, 4 + $wi)
				@ui_box(0, 0, $desk_w, $desk_h, $th_panel, $th_line)
				if $wf != ""
					@xf_render($wf, $cw * 0.4, $chh * 0.4, $desk_w - $cw * 0.8, $desk_h - $chh * 0.8, $wa)
			else
				@text_fit_c($desk_w / 2, $desk_h / 2 - $chh / 2, $th_dim, "APP OFFLINE", $desk_w)
	@slot_present($k, 0, 0, $cur_w, $cur_h)
	$desk_w = $sv_dw
	$desk_h = $sv_dh
	$disp_mode = $sv_mode
	$sc_pos = $sv_sc
	$hit_on = $sv_hit
	$hit_sl_cur = $sv_hsl
	$ox = 0
	$oy = 0

; ---- Settings > Display > OTHER SCREENS ----
function @page_pj_list()
	$sl_txt.clear()
	$sl_spec.clear()
	$pj_slots.clear()
	var $others = 0
	repeat $slot_n ($k)
		if ($sl_role.$k == 2) and (@jn_lead_of($k) == $k)
			var $lb = text("{} #{}:  ", $sl_alias.$k, $sl_ch.$k) & @pj_label(@pj_kind_of($k), @pj_ref_of($k))
			var $jc = 0
			repeat $slot_n ($q)
				if @jn_lead_of($q) == $k
					$jc += 1
			if $jc > 1
				$lb = text("[{} JOINED] ", $jc) & $lb
			$sl_txt.append($lb)
			$pj_slots.append($k)
			$others += 1
	if $others >= 2
		$sl_txt.append("+ JOIN SCREENS INTO ONE BIG SCREEN")
		$pj_slots.append(-2)
	var $jn = $jn_mem.size
	repeat $jn ($j)
		$sl_txt.append("SPLIT: " & replace(substring($jn_mem.$j, 1, size($jn_mem.$j) - 2), "|", " + "))
		$pj_slots.append(-100 - $j)
	var $hint = "Tap one to choose what it shows. (You can also press and hold on that screen.)"
	if $sl_txt.size == 0
		$hint = "There are no other screens. Add a dashboard (with an alias) to the network."
	@pick_list("OTHER SCREENS", $hint, "pj_tgt")

function @page_pj_choose()
	if ($pj_target < 0) or ($pj_target >= $slot_n)
		@go("pj_list")
		return
	@pj_rows()
	var $t = text("SHOW ON {} #{}", $sl_alias.$pj_target, $sl_ch.$pj_target)
	@pick_list($t, "", "pj_pick2")

; ---- joining other screens (Settings > Display > OTHER SCREENS) ----
function @jn_start()
	$jn_mode = 1
	$jn_tap.clear()
	$jn_new_cols = 2
	$pj_pick = -1
	$panels_dirty = 1
	@go("pj_join")

function @jn_end()
	$jn_mode = 0
	$jn_tap.clear()
	$panels_dirty = 1

; Default columns: 2 or 4 screens -> 2 wide... 3 -> a row of 3.
function @jn_default_cols($n : number) : number
	if $n == 3
		return 3
	return min($n, 2)

function @jn_tap_slot($k : number)
	var $n = $jn_tap.size
	repeat $n ($q)
		if $jn_tap.$q == $k
			; tapping a numbered one starts over
			$jn_tap.clear()
			$ui_dirty = 1
			return
	if $n >= 4
		@ui_toast("UP TO 4 SCREENS")
		return
	if $n > 0
		var $f = $jn_tap.0
		if ($sl_w.$k != $sl_w.$f) or ($sl_h.$k != $sl_h.$f)
			@ui_toast("SCREENS MUST BE THE SAME SIZE")
			return
	$jn_tap.append($k)
	$jn_new_cols = @jn_default_cols($jn_tap.size)
	@snd_beep(880, 0.06)
	$ui_dirty = 1

function @jn_save()
	var $n = $jn_tap.size
	if $n < 2
		return
	; a screen can only be in one join
	repeat $n ($q)
		@jn_split($jn_tap.$q)
	var $m = "|"
	repeat $n ($q2)
		$m = $m & @jn_key($jn_tap.$q2) & "|"
	$jn_mem.append($m)
	$jn_cols.append($jn_new_cols)
	@jn_end()
	@jn_build()
	@go("pj_list")

; Main-screen page while joining.
function @page_pj_join()
	var $y = @set_header("JOIN SCREENS")
	var $tw = min($content_w, $cw * 60)
	$y = @ui_para_l($content_x, $y, $th_dim, "Tap the other screens in reading order (top-left first, row by row). Up to 4 screens of the same size. Tap a numbered screen to start over.", $tw)
	$y += $chh * 0.5
	var $n = $jn_tap.size
	$y = @ui_para_l($content_x, $y, $th_accent, text("SCREENS TAPPED: {}", $n), $tw)
	if $n >= 2
		var $rows = ceil($n / $jn_new_cols)
		$y = @set_stepper($y, "LAYOUT", text("{} WIDE x {} HIGH", $jn_new_cols, $rows), "jn_cols-", "jn_cols+")
		; little preview
		var $pw = $cw * 4
		var $ph = $chh * 2
		$y = @bz_fit($y, $ph * $rows + $chh)
		repeat $n ($q)
			var $px = $content_x + mod($q, $jn_new_cols) * ($pw + 2)
			var $py = $y + floor($q / $jn_new_cols) * ($ph + 2)
			@ui_box($px, $py, $pw, $ph, $th_ok_dk, $th_ok)
			@ui_text_c($px + $pw / 2, $py + ($ph - $chh) / 2, $th_ok, text("{}", $q + 1))
		$y += $rows * ($ph + 2) + $chh * 0.6
	var $bh = $chh * 2.6
	var $hb = ($tw - $cw) / 2
	$y = @bz_fit($y, $bh)
	@ui_btn($content_x, $y, $hb, $bh, "CANCEL", "jn_cancel", 0)
	var $st = 3
	if $n < 2
		$st = 4
	@ui_btn($content_x + $hb + $cw, $y, $hb, $bh, "JOIN", "jn_save", $st)

function @jn_action($act : text, $val : number)
	if $act == "jn_tap"
		$ui_dirty = 1
	elseif $act == "jn_cancel"
		@jn_end()
		@go("pj_list")
	elseif $act == "jn_save"
		@jn_save()
	elseif ($act == "jn_cols-") or ($act == "jn_cols+")
		var $n = $jn_tap.size
		var $c = $jn_new_cols
		repeat $n ($q)
			if $act == "jn_cols+"
				$c += 1
			else
				$c -= 1
			if $c < 1
				$c = $n
			if $c > $n
				$c = 1
			if mod($n, $c) == 0
				$jn_new_cols = $c
				$ui_dirty = 1
				return
	$ui_dirty = 1
	$panels_dirty = 1

; ChipOS - pages: first-run wizard, Home, Devices, Device detail, Setup.
storage var $os_setup_done : number
var $dv_filter = 0
var $dv_sel = -1
var $dv_suggest = ""
var $dv_list_rev = -1
var $dv_list_filter = -1
array $lst : number
array $rows_y : number
var $wz_deadline = 0
var $wz_return = "home"

function @go($pg : text)
	if ($ui_page == "xapp") and ($pg != "xapp") and (!@pj_shows_app($xa_cur))
		var $gc = @clk_text()
		var $gd = @clk_day()
		@xa_send("close", "", $gc, $gd, $cfg_units, "")
	$ui_page = $pg
	$sc_pos = 0
	$pg_sy = 0
	$pg_lim = 0
	$ui_dirty = 1

; ---------------- DEVICES ----------------
function @dv_build_list()
	if ($dv_list_rev == $db_rev) and ($dv_list_filter == $dv_filter)
		return
	$dv_list_rev = $db_rev
	$dv_list_filter = $dv_filter
	$lst.clear()
	var $bl_n = $db_id.size
	repeat $cat_count ($bl_ci)
		var $bl_c = mod($bl_ci + 1, $cat_count)
		repeat $bl_n ($bl_j)
			if $db_cat.$bl_j == $bl_c
				var $bl_present = ($db_seen.$bl_j >= $scan_gen - 1)
				var $bl_ok = 1
				if $dv_filter == 1
					$bl_ok = $bl_present and @db_needs_name($bl_j)
				elseif $dv_filter == 2
					$bl_ok = !$bl_present
				if $bl_ok
					$lst.append($bl_j)

function @page_devices()
	@dv_build_list()
	var $px = $content_x
	var $py = $content_y
	var $pw = $content_w
	var $fb_h = $chh * 2.2
	var $fb_w = min($pw / 3, $cw * 22)
	var $f0 = text("ALL ({})", $db_id.size)
	var $f1 = text("NEED NAME ({})", $db_unnamed)
	var $f2 = text("MISSING ({})", $db_missing)
	var $fs0 = 0
	var $fs1 = 0
	var $fs2 = 0
	if $dv_filter == 0
		$fs0 = 1
	elseif $dv_filter == 1
		$fs1 = 1
	else
		$fs2 = 1
	@ui_btn($px, $py, $fb_w - $cw * 0.5, $fb_h, $f0, "flt:0", $fs0)
	@ui_btn($px + $fb_w, $py, $fb_w - $cw * 0.5, $fb_h, $f1, "flt:1", $fs1)
	@ui_btn($px + $fb_w * 2, $py, $fb_w - $cw * 0.5, $fb_h, $f2, "flt:2", $fs2)
	var $ly = $py + $fb_h + $chh * 0.6
	var $lbot = $content_y + $content_h
	var $sb_w = max($cw * 3, 18)
	var $rh = $chh * 2.2
	var $ncol = max(1, floor(($pw - $sb_w - $cw) / ($cw * 42)))
	var $colw = ($pw - $sb_w - $cw) / $ncol
	var $rw = $colw - $cw
	; Row positions down one column, skipping screen edges.
	$rows_y.clear()
	var $ry_cur = $ly
	repeat 200 ($rk)
		var $ry_fit = @bz_fit($ry_cur, $rh - 2)
		if $ry_fit + $rh - 2 <= $lbot
			$rows_y.append($ry_fit)
			$ry_cur = $ry_fit + $rh
	var $per_col = max($rows_y.size, 1)
	$sc_total = $lst.size
	$sc_vis = $per_col * $ncol
	@ui_scroll_clamp()
	if $sc_total == 0
		@ui_text_c($px + $rw / 2, $ly + $chh * 2, $th_dim, "NOTHING HERE")
	var $name_chars = floor(($rw * 0.62) / $cw)
	repeat $sc_vis ($r)
		var $li = $sc_pos + $r
		if $li < $sc_total
			var $j = $lst.$li
			var $r_c = floor($r / $per_col)
			var $r_i = $r - $r_c * $per_col
			var $ry = $rows_y.$r_i
			var $rx = $px + $r_c * $colw
			var $r_cat = $db_cat.$j
			var $r_col = @cat_color($r_cat)
			@ui_box($rx, $ry, $rw, $rh - 2, $th_panel, $th_line)
			@ui_box($rx, $ry, $cw * 0.7, $rh - 2, $r_col, $r_col)
			var $r_name = @db_name($j)
			var $r_name_f = @ui_fit($r_name, $name_chars)
			var $r_ink = $th_text
			if $db_alias.$j == ""
				$r_ink = $th_warn
			@ui_text($rx + $cw * 1.5, $ry + ($rh - $chh) / 2 - 1, $r_ink, $r_name_f)
			var $r_status = @cat_name($r_cat)
			var $r_scol = $th_dim
			if ($db_seen.$j < $scan_gen - 1)
				$r_status = "MISSING"
				$r_scol = $th_bad
			elseif @db_needs_name($j)
				$r_status = "NEEDS NAME"
				$r_scol = $th_warn
			elseif $db_on.$j == 1
				$r_status = "ON"
				$r_scol = $th_ok
			elseif $db_on.$j == 0
				$r_status = "OFF"
			@ui_text_r($rx + $rw - $cw, $ry + ($rh - $chh) / 2 - 1, $r_scol, $r_status)
			$ui_hv = $j
			@ui_hit($rx, $ry, $rx + $rw, $ry + $rh - 2, "row")
	@ui_scrollbar($px + $pw - $sb_w, $ly, $sb_w, $lbot - $ly)

; ---------------- DEVICE DETAIL ----------------
function @detail_line($dl_y : number, $dl_k : text, $dl_v : text)
	@ui_text($content_x + $cw, $dl_y, $th_dim, $dl_k)
	@ui_text($content_x + $cw * 12, $dl_y, $th_text, $dl_v)

function @page_detail()
	if ($dv_sel < 0) or ($dv_sel >= $db_id.size)
		@go("devices")
		return
	var $j = $dv_sel
	var $dx = $content_x
	var $dy = $content_y
	var $bw = $cw * 10
	var $bh = $chh * 2.2
	@ui_btn($dx, $dy, $bw, $bh, "< BACK", "back", 0)
	var $d_name = @db_name($j)
	var $d_title = @ui_fit($d_name, floor(($content_w - $bw - $cw * 2) / $cw))
	var $d_cat = $db_cat.$j
	var $d_col = @cat_color($d_cat)
	@ui_text($dx + $bw + $cw, $dy + ($bh - $chh) / 2, $d_col, $d_title)
	var $y = $dy + $bh + $chh
	var $lh = $chh * 1.5
	var $d_id = $db_id.$j
	var $d_present = ($db_seen.$j >= $scan_gen - 1)
	var $d_type = $db_type.$j
	var $d_catn = @cat_name($d_cat)
	$y = @bz_fit($y, $chh)
	@detail_line($y, "TYPE", $d_type & "  (" & $d_catn & ")")
	$y += $lh
	var $d_alias = $db_alias.$j
	if $d_alias == ""
		$d_alias = "-"
	$y = @bz_fit($y, $chh)
	@detail_line($y, "ALIAS", $d_alias)
	$y += $lh
	$y = @bz_fit($y, $chh)
	@detail_line($y, "ID", $d_id)
	$y += $lh
	if $d_present
		var $dv = device($d_id)
		var $dv_x = $dv.x:number
		var $dv_y = $dv.y:number
		var $dv_z = $dv.z:number
		var $dv_px = @fmt_len($dv_x)
		var $dv_py = @fmt_len($dv_y)
		var $dv_pz = @fmt_len($dv_z)
		var $dv_pos = $dv_px & ", " & $dv_py & ", " & $dv_pz
		$y = @bz_fit($y, $chh)
		@detail_line($y, "POSITION", $dv_pos)
		$y += $lh
		var $dv_sx = $dv.size_x:number
		var $dv_sy = $dv.size_y:number
		var $dv_sz = $dv.size_z:number
		var $dv_m = $dv.mass:number
		var $dv_sxt = @fmt_len($dv_sx)
		var $dv_syt = @fmt_len($dv_sy)
		var $dv_szt = @fmt_len($dv_sz)
		var $dv_mt = @fmt_mass($dv_m)
		var $dv_size = $dv_sxt & " x " & $dv_syt & " x " & $dv_szt & "   " & $dv_mt
		$y = @bz_fit($y, $chh)
		@detail_line($y, "SIZE", $dv_size)
		$y += $lh
		var $dv_t = $dv.temp:number
		var $dv_dmg = $dv.damage:number
		var $dv_c = $dv_t - 273.15
		var $dv_tt = @fmt_temp($dv_c)
		var $dv_health = $dv_tt & text("   DAMAGE {0}%", $dv_dmg)
		$y = @bz_fit($y, $chh)
		@detail_line($y, "HEALTH", $dv_health)
		$y += $lh
	else
		$y = @bz_fit($y, $chh)
		@detail_line($y, "STATUS", "MISSING - not on the data network")
		$y += $lh
	if $d_present and ($db_alias.$j != "")
		$y = @bz_fit($y, $chh)
		var $rc_a = $db_alias.$j
		var $rc_t = "RAW IN"
		repeat 8 ($rc)
			var $rc_v = @in_n($rc_a, $rc)
			$rc_t = $rc_t & text("  {}:{0.00}", $rc, $rc_v)
		var $rc_f = @ui_fit($rc_t, floor($content_w / $cw))
		@ui_text($content_x + $cw, $y, $th_dim, $rc_f)
		$y += $chh * 1.5
	$y += $chh * 0.6
	if $d_present and @db_needs_name($j)
		var $bx_h = $chh * 6.4
		if $content_w < $cw * 60
			$bx_h = $chh * 9.5
		$y = @bz_fit($y, $bx_h)
		@ui_box($dx, $y, $content_w, $bx_h, $th_panel, $th_warn)
		var $nb_cx = $dx + $content_w / 2
		var $nb_y = @ui_para_c($nb_cx, $y + $chh * 0.6, $th_warn, "NEEDS A NAME BEFORE CHIPOS CAN CONTROL IT", $content_w - $cw * 2)
		var $sg_line = "SUGGESTED ALIAS:  " & $dv_suggest
		$nb_y = @ui_para_c($nb_cx, $nb_y + $chh * 0.3, $th_text, $sg_line, $content_w - $cw * 2)
		$nb_y = @ui_para_c($nb_cx, $nb_y + $chh * 0.3, $th_dim, "Look at it, press V, set its alias. ChipOS picks it up within 3 seconds.", $content_w - $cw * 2)
		$y += $bx_h + $chh * 0.6
	if $d_present and ($db_alias.$j != "") and (($d_cat == 1) or ($d_cat == 2))
		var $cb_w = min($content_w / 3, $cw * 18)
		$y = @bz_fit($y, $bh)
		var $cur = $db_on.$j
		var $st_on = 0
		var $st_off = 0
		var $st_free = 0
		if $cur == 1
			$st_on = 3
		elseif $cur == 0
			$st_off = 1
		else
			$st_free = 1
