function @wiz_frame($wf_title : text, $wf_step : text)
	@ui_box(0, 0, $desk_w, $chh * 2.4, $th_panel, $th_line)
	@ui_text($cw, $chh * 0.7, $th_accent, "ChipOS SETUP")
	@ui_text_r($desk_w - $cw, $chh * 0.7, $th_dim, $wf_step)
	@ui_text_big($desk_w / 2, $chh * 4, $th_text, $wf_title, 1.6)

function @wiz_welcome()
	@ui_text_big($desk_w / 2, $desk_h * 0.16, $th_accent, "ChipOS", 3)
	@ui_text_c($desk_w / 2, $desk_h * 0.16 + $chh * 3.6, $th_dim, $os_version)
	var $ww1 = text("Found {} devices and {} screens.", $db_present, $slot_n)
	var $wy = @ui_para_c($desk_w / 2, $desk_h * 0.46, $th_text, $ww1, $desk_w * 0.9)
