	var $bw = min($desk_w * 0.5, $cw * 18)
	var $bh = $chh * 2.6
	@ui_btn($desk_w / 2 - $bw / 2, $desk_h * 0.72, $bw, $bh, "NEXT", "wz:next", 3)

function @wiz_detect()
	@wiz_frame("SCREENS", "STEP 1")
	var $y = $chh * 8
	var $bw = min($desk_w * 0.8, $cw * 34)
	var $bh = $chh * 2.6
	var $bx = $desk_w / 2 - $bw / 2
	if $grp_n >= 2
		@ui_text_c($desk_w / 2, $y, $th_text, "AUTO-DETECT SCREENS?")
		var $wd1 = text("'{}' has {} matching screens. ChipOS can spread one desktop across them.", $grp_alias, $grp_n)
		var $wdy = @ui_para_c($desk_w / 2, $y + $chh * 1.8, $th_dim, $wd1, $desk_w * 0.9)
		@ui_btn($bx, $y + $chh * 5.5, $bw, $bh, "YES, TRY IT", "wz:yes", 3)
		@ui_btn($bx, $y + $chh * 5.5 + $bh * 1.4, $bw, $bh, "NO, USE THIS SCREEN", "wz:no", 0)
	else
		@ui_text_c($desk_w / 2, $y, $th_text, text("USING THIS SCREEN ({} x {}).", $desk_w, $desk_h))
		var $wdy2 = @ui_para_c($desk_w / 2, $y + $chh * 1.8, $th_dim, "No group of matching screens was found.", $desk_w * 0.9)
		@ui_btn($bx, $y + $chh * 5.5, $bw, $bh, "NEXT", "wz:no", 3)

function @wiz_only()
	@wiz_frame("SCREENS", "STEP 1")
	var $y = $chh * 8
	var $bw = min($desk_w * 0.8, $cw * 34)
	var $bh = $chh * 2.6
	var $bx = $desk_w / 2 - $bw / 2
	var $wo1 = text("Is '{}' made ONLY of screens?", $grp_alias)
