; Shown on the main screen only if it is not one of the numbered screens.
function @wiz_identify()
	@wiz_frame("SCREENS", "STEP 1")
	@ui_text_c($desk_w / 2, $chh * 8, $th_text, "TAP THE NUMBERED SCREENS")
	@ui_text_c($desk_w / 2, $chh * 9.6, $th_dim, "top-left first, then row by row")
	var $bw = min($desk_w * 0.6, $cw * 20)
	@ui_btn($desk_w / 2 - $bw / 2, $chh * 13, $bw, $chh * 2.6, "CANCEL", "wz:undo", 0)

function @wiz_confirm()
	var $cf_n = $span_order.size
	var $cf_rows = ceil($cf_n / max($span_cols, 1))
	; Test pattern: every screen outlined + numbered, one diagonal across all.
	repeat $cf_n ($ci)
		var $cxx = mod($ci, $span_cols) * $grp_w
		var $cyy = floor($ci / $span_cols) * $grp_h
		@d_rect($cxx + 1, $cyy + 1, $cxx + $grp_w - 2, $cyy + $grp_h - 2, $th_line, $th_bg)
		var $cnum = text("{}", $ci + 1)
		@ui_text($cxx + $cw, $cyy + $chh * 0.6, $th_dim, $cnum)
	repeat 3 ($cl)
		@d_line($cl, 0, $desk_w - 3 + $cl, $desk_h - 1, $th_accent)
		@d_line($desk_w - 3 + $cl, 0, $cl, $desk_h - 1, $th_accent)
	@ui_text_big($desk_w / 2, $desk_h * 0.12, $th_accent, "ChipOS", 4)
	var $dw = min($desk_w * 0.7, $cw * 52)
	var $dh = $chh * 11
	var $ddx = $desk_w / 2 - $dw / 2
	var $ddy = $desk_h / 2 - $dh / 2
	@ui_box($ddx, $ddy, $dw, $dh, $th_panel, $th_accent)
	@ui_text_c($desk_w / 2, $ddy + $chh * 0.8, $th_text, "KEEP THESE SETTINGS?")
	var $cf_l = text("{} x {} screens. The lines should run straight", $span_cols, $cf_rows)
	@ui_text_c($desk_w / 2, $ddy + $chh * 2.3, $th_dim, $cf_l)
	@ui_text_c($desk_w / 2, $ddy + $chh * 3.4, $th_dim, "corner to corner and the title read unbroken.")
	var $left = max(0, ceil($wz_deadline - time))
	var $cf_r = text("Reverting in {} s", $left)
	@ui_text_c($desk_w / 2, $ddy + $chh * 4.6, $th_warn, $cf_r)
	var $hbw = ($dw - $cw * 3) / 2
	var $bh = $chh * 2.2
	@ui_btn($ddx + $cw, $ddy + $chh * 6.0, $hbw, $bh, "- COLUMNS", "wz:colsm", 0)
	@ui_btn($ddx + $cw * 2 + $hbw, $ddy + $chh * 6.0, $hbw, $bh, "+ COLUMNS", "wz:colsp", 0)
	@ui_btn($ddx + $cw, $ddy + $chh * 8.5, $hbw, $bh, "KEEP", "wz:keep", 3)
	@ui_btn($ddx + $cw * 2 + $hbw, $ddy + $chh * 8.5, $hbw, $bh, "UNDO", "wz:undo", 2)

function @wiz_what()
	@wiz_frame("WHAT AM I?", "STEP 2")
	var $wy = @ui_para_c($desk_w / 2, $chh * 7, $th_dim, $ar_reason, $desk_w * 0.9)
	var $bw = min($desk_w * 0.94, $cw * 62)
	var $bx = $desk_w / 2 - $bw / 2
	var $bh = $chh * 2.6
	$wy += $chh * 0.5
	repeat 5 ($wa)
		$wy = @bz_fit($wy, $bh)
		var $wa_st = 0
		if $wa == $ar_sel
			$wa_st = 1
		var $wa_name = @arch_name($wa)
		var $wa_desc = @arch_desc($wa)
		var $wa_lab = $wa_name & " - " & $wa_desc
		if $wa == $ar_guess
			$wa_lab = "* " & $wa_lab & " (DETECTED)"
		if size($wa_lab) * $cw > $bw - $cw * 2
			$wa_lab = $wa_name
			if $wa == $ar_guess
				$wa_lab = "* " & $wa_name & " (DETECTED)"
		$ui_hv = $wa
		@ui_btn($bx, $wy, $bw, $bh, $wa_lab, "ar", $wa_st)
		$wy += $bh + $chh * 0.5
	$wy = @bz_fit($wy + $chh * 0.5, $bh)
	var $nb = min($desk_w * 0.5, $cw * 18)
	@ui_btn($desk_w / 2 - $nb / 2, $wy, $nb, $bh, "NEXT", "wz:what_next", 3)

function @wiz_sub()
	var $sq = @arch_question($ar_sel)
	@wiz_frame($sq, "STEP 3")
	var $bw = min($desk_w * 0.9, $cw * 40)
	var $bx = $desk_w / 2 - $bw / 2
	var $bh = $chh * 2.6
	var $sy = $chh * 7.5
	var $sn = @sub_count($ar_sel)
	repeat $sn ($ss)
		$sy = @bz_fit($sy, $bh)
		var $ss_st = 0
		if $ss == $ar_sub_sel
			$ss_st = 1
		var $ss_lab = @sub_name($ar_sel, $ss)
		if ($ar_sel == $ar_guess) and ($ss == $ar_sub_guess)
			$ss_lab = $ss_lab & "  (DETECTED)"
		$ui_hv = $ss
		@ui_btn($bx, $sy, $bw, $bh, $ss_lab, "sub", $ss_st)
		$sy += $bh + $chh * 0.5
	$sy = @bz_fit($sy + $chh * 0.5, $bh)
	var $hb = ($bw - $cw) / 2
	@ui_btn($bx, $sy, $hb, $bh, "< BACK", "wz:sub_back", 0)
	@ui_btn($bx + $hb + $cw, $sy, $hb, $bh, "NEXT", "wz:sub_next", 3)

function @wiz_finish()
	@wiz_frame("ALL SET", "DONE")
	var $wf_a = @arch_name($cfg_arch)
	var $wf_s = @sub_name($cfg_arch, $cfg_sub)
	var $wf_l = text("This build: {} / {}", $wf_a, $wf_s)
	var $wfy = @ui_para_c($desk_w / 2, $chh * 8, $th_text, $wf_l, $desk_w * 0.9)
	$wfy = @ui_para_c($desk_w / 2, $wfy, $th_dim, "Your home screen starts empty: press and hold on it to add widgets and app shortcuts. Lights, tanks, solar and crafting arrive as apps in the next updates.", $desk_w * 0.9)
	var $bw = min($desk_w * 0.6, $cw * 20)
	var $fin_y = max($chh * 13, $wfy + $chh)
	@ui_btn($desk_w / 2 - $bw / 2, $fin_y, $bw, $chh * 2.6, "FINISH", "wz:finish", 3)
	if ($disp_mode == 0) and ($grp_n >= 2)
		var $bw2 = min($desk_w * 0.9, $cw * 30)
		@ui_btn($desk_w / 2 - $bw2 / 2, $fin_y + $chh * 3.6, $bw2, $chh * 2.6, "TRY SCREEN SETUP AGAIN", "wz:next", 0)

