; ChipOS - SETTINGS app.
function @set_header($t : text) : number
	@ui_text($content_x, $content_y, $th_accent, $t)
	return $content_y + $chh * 2

; One settings row: title + subtitle, tappable.
function @set_row($y : number, $title : text, $sub : text, $act : text, $col : number) : number
	var $rh = $chh * 3
	$y = @bz_fit($y, $rh)
	var $w = min($content_w, $cw * 60)
	@ui_box($content_x, $y, $w, $rh - 2, $th_panel, $th_line)
	@d_circle($content_x + $chh * 1.5, $y + $rh / 2 - 1, $chh * 0.7, $col, $col)
	@ui_text($content_x + $chh * 3, $y + $chh * 0.35, $th_text, $title)
	var $sf = @ui_fit($sub, floor(($w - $chh * 4) / $cw))
	@ui_text($content_x + $chh * 3, $y + $chh * 1.45, $th_dim, $sf)
	@ui_hit($content_x, $y, $content_x + $w, $y + $rh - 2, $act)
	return $y + $rh + $chh * 0.3

; A labelled - value + line.
function @set_stepper($y : number, $label : text, $value : text, $am : text, $ap : text) : number
	var $bh = $chh * 2.2
	$y = @bz_fit($y, $bh)
	var $w = min($content_w, $cw * 60)
	var $bw = $cw * 5
