; Zone list with each zone's current time -> $sl_txt
function @tz_rows_add()
	var $n = $tz_nm.size
	repeat $n ($z)
		@clk_calc($z, 0)
		var $zo = @fmt_utc($ck_off)
		var $zt = @fmt_hm($ck_h, $ck_mi, $cfg_24h)
		var $zn = $tz_nm.$z
		if $z == @tz_custom()
			$zn = "Custom UTC offset (adjust in Settings)"
		$sl_txt.append($zt & "   " & $zo & "   " & $zn)

function @tz_rows()
	if @sl_cached("tz")
		return
	$sl_txt.clear()
	$sl_spec.clear()
	@tz_rows_add()

