var $boot_ok = 0
var $disc_next = 0

init
	@os_log(text("{} {} booting", $os_name, $os_version))
	@clk_init()
	@db_load()
	@dv_load()
	@ba_init()
	@cm_load()
	@tsv_load()
	@cr_load()
	@sx_load()
	@ws_load()
	@so_load()
	@rz_load()
	@fl_load()
	@mn_load()
	@fy_load()
	@disp_load()
	@arch_load()
	@pw_load()
	@shell_load()
	@hm_load()
	@scan_all()
	@lt_jfix()
	@home_order_build()
	@os_log(text("{} devices on the data network ({} known)", $db_present, $db_id.size))
	@kb_layout()
	@disp_discover()
	@disp_alloc_rt()
	@disp_apply_saved()
	if $os_setup_done
		@go("home")
	else
		@go("wiz_welcome")
		; several dashboards: first ask which one ChipOS runs on
		if (@disp_dash_count() >= 2) and ($cfg_main_alias == "")
			$pick_main = 1
			$panels_dirty = 1
	if $slot_n == 0
		@os_log("No screen found: give a dashboard an alias (V menu) - ChipOS will find it.")
	$boot_t = time
	$boot_ok = 1

update
	@scan_tick()
	@pw_tick()
	@au_tick()
	@rz_tick()
	@odo_tick()
	@dv_tick()
	@dv_ui_tick()
	@ba_tick()
	@cm_tick()
	@tsv_tick()
	@cr_tick()
	@sx_tick()
	@cr_ful_tick()
	@ws_tick()
	@so_tick()
	@wt_tick()
	@fl_tick()
	@fy_tick()
	@kv_tick()
	@kf_tick()
	@mn_tick()
	@ask_tick()
	@db_assert()
	if $pw_note != ""
		@notify($pw_note)
		$pw_note = ""
	if $pw_nq.size > 0
		@notify($pw_nq.0)
		$pw_nq.erase(0)
	@snd_tick()
	@xa_scan()
	if @ba_is_builtin_name($xa_back)
		$xa_back = ""
	if $xa_back != ""
		@notify("App reinstalled: " & upper($xa_back))
		$xa_back = ""
	if @ba_is_builtin_name($xa_lost)
		$xa_lost = ""
	if $xa_lost != ""
		if $ui_page == "xapp"
			@go("home")
		@notify("App disconnected: " & upper($xa_lost))
		$xa_lost = ""
	if @ba_is_builtin_name($xa_new)
		$xa_new = ""
	if $xa_new != ""
		@notify("New app installed: " & upper($xa_new))
		$xa_new = ""
	if $xa_warn_new
		$xa_warn_new = 0
		@notify("ADD-ON APPS CAN'T REACH CHIPOS: GIVE THIS COMPUTER THE ALIAS chipos")
	@kb_tick()
	@cw_tick()
	; Widget builder: the name was typed (or cancelled) on the keyboard.
	if $kb_int_done and ($kb_id == "gpname")
		var $gpn = replace(replace($kb_int_text, ",", " "), ":", " ")
		if ($kb_int_done == 1) and ($gpn != "")
			$gp_name.append($gpn)
			$gp_mem.append(",")
			$gp_cur = $gp_name.size - 1
			@go("gp_edit")
		elseif $gp_back != ""
			@go($gp_back)
		else
			@go("power")
		if $gp_back == ""
			$pw_sub = 3
		$kb_int_done = 0
	if $kb_int_done and (find($kb_id, "cm_") == 0)
		@cm_kb_done($kb_id, $kb_int_done == 1, $kb_int_text)
		$kb_int_done = 0
	if $kb_int_done and (find($kb_id, "rf_") == 0)
		@fl_kb_done($kb_id, $kb_int_done == 1, $kb_int_text)
		$kb_int_done = 0
	if $kb_int_done and (find($kb_id, "ws_") == 0)
		@ws_kb_done($kb_id, $kb_int_done == 1, $kb_int_text)
		$kb_int_done = 0
	if $kb_int_done and (find($kb_id, "cr_") == 0)
		@cr_kb_done($kb_id, $kb_int_done == 1, $kb_int_text)
		$kb_int_done = 0
	if $kb_int_done and (find($kb_id, "rz_") == 0)
		@rz_kb_done($kb_id, $kb_int_done == 1, $kb_int_text)
		$kb_int_done = 0
	if $kb_int_done and (find($kb_id, "ba_") == 0)
		@ba_kb_done($kb_id, $kb_int_done == 1, $kb_int_text)
		$kb_int_done = 0
	if $kb_int_done
		if $kb_int_done == 1
			$cwn_label = $kb_int_text
			if $cwn_label == ""
				$cwn_label = "WIDGET"
			@go("cw_size")
		else
			@go("home")
		$kb_int_done = 0
	; Beep requests from any app (first look after boot only records them).
	var $bn = $xa_alias.size
	repeat $bn ($bi)
		if ($bi < $xa_bpq.size) and $xa_online.$bi
			var $bq = @in_t($xa_alias.$bi, 3)
			if $bq != $xa_bpq.$bi
				if $xa_bpq.$bi != ""
					var $bf = $bq.f:number
					var $bd = $bq.d:number
					@snd_beep(clamp($bf, 50, 8000), clamp($bd, 0.02, 3))
				$xa_bpq.$bi = $bq
				if $bq == ""
					$xa_bpq.$bi = "-"
	; Keyboard requests from the open app.
	if ($ui_page == "xapp") and ($xa_cur >= 0) and ($xa_cur < $xa_inq.size) and (!$kb_on)
		var $iq = @in_t($xa_alias.$xa_cur, 2)
		if ($iq != $xa_inq.$xa_cur) and ($iq != "")
			$xa_inq.$xa_cur = $iq
			@kb_open($xa_cur, $iq.id, $iq.prompt, $iq.init)
	; Open app: redraw when its screen changes; send the clock once a minute.
	if $ui_page == "xapp"
		if ($xa_cur >= 0) and ($xa_cur < $xa_alias.size)
			var $xf_now = @in_t($xa_alias.$xa_cur, 1)
			if $xf_now != $xa_frame_seen
				$ui_dirty = 1
		if time >= $xa_tick_next
			$xa_tick_next = time + 60
			var $xt_c = @clk_text()
			var $xt_d = @clk_day()
			@xa_send("tick", "", $xt_c, $xt_d, $cfg_units, "")
	; No screen yet: look again every 5 s.
	; on the computer's own screen: switch once a dashboard shows up
	if $disp_own_only and (time >= $disc_next)
		$disc_next = time + 5
		if @disp_dash_exists()
			reboot()
	if ($slot_n == 0) and (time >= $disc_next)
		$disc_next = time + 5
		@disp_discover()
		if $slot_n > 0
			; First screen appeared after startup: restart to size the buffer.
			reboot()
	if $db_rev != $ui_rev_drawn
		$ui_rev_drawn = $db_rev
		$ui_dirty = 1
		$panels_dirty = 1
	@drawer_tick()
	@pj_keepalive()
	@ui_frame()
	@att_fast()
	@panels_tick()

include "clicks.xc"

; ChipOS - attitude display (artificial horizon + heading / speed / altitude
; tapes). Reads the first named Nav Instrument: ch0 airspeed m/s, ch1
; vertical speed m/s, ch2 altitude (sea level) m, ch3 height above ground m,
; ch4 pitch and ch5 roll (x180 = degrees), ch6 heading degrees.
var $att_nav = ""
var $att_nav_next = 0
var $att_live = 0                       ; an attitude display is on screen
array $att_rx1 : number                 ; home tiles holding one (desktop px)
array $att_ry1 : number
array $att_rx2 : number
array $att_ry2 : number

function @att_find_nav()
	if time < $att_nav_next
		return
	$att_nav_next = time + 3
	$att_nav = ""
	var $n = $db_id.size
	repeat $n ($j)
		if ($att_nav == "") and contains($db_type.$j, "NavInstrument") and ($db_alias.$j != "") and ($db_seen.$j >= $scan_gen - 1)
			$att_nav = $db_alias.$j

; Clip a line to the box (simple: skip lines with an end outside).
function @att_line($x1 : number, $y1 : number, $x2 : number, $y2 : number, $bx : number, $by : number, $bw : number, $bh : number, $c : number)
	if ($x1 < $bx) or ($x2 < $bx) or ($x1 > $bx + $bw) or ($x2 > $bx + $bw)
		return
	if ($y1 < $by) or ($y2 < $by) or ($y1 > $by + $bh) or ($y2 > $by + $bh)
		return
	@d_line($x1, $y1, $x2, $y2, $c)

function @att_text_c($cx : number, $y : number, $c : number, $t : text, $by : number, $bh : number)
	if ($y < $by) or ($y + $chh > $by + $bh)
		return
	@ui_text_c($cx, $y, $c, $t)

; Horizon with pitch ladder, bank scale and aircraft symbol.
function @att_horizon($x : number, $y : number, $w : number, $h : number, $pitch : number, $roll : number)
	var $sky = color(36, 92, 170)
	var $gnd = color(118, 78, 40)
	var $cx = $x + $w / 2
	var $cy = $y + $h / 2
	var $ppd = $h / 50                  ; pixels per degree: +-25 deg visible
	var $r = $roll * pi / 180
	var $cr = cos($r)
	var $sr = sin($r)
	var $crs = $cr
	if abs($crs) < 0.02
		$crs = 0.02
		if $cr < 0
			$crs = -0.02
	var $inv = $cr < 0
	; horizon centre: pitch moves it along the aircraft's "down" direction
	var $hcx = $cx + $sr * $pitch * $ppd
	var $hcy = $cy + $cr * $pitch * $ppd
	var $tn = $sr / $crs
	; fill column by column: sky above the horizon line, ground below
	var $step = max(1, floor($w / 160))
	var $cols = floor($w / $step) + 1
	var $top_c = $sky
	var $bot_c = $gnd
	if $inv
		$top_c = $gnd
		$bot_c = $sky
	repeat $cols ($k)
		var $px = $x + $k * $step
		var $pxe = min($px + $step, $x + $w)
		var $hy = $hcy - ($px + $step / 2 - $hcx) * $tn
		var $yb = clamp($hy, $y, $y + $h)
		if $yb > $y
			@d_rect($px, $y, $pxe, $yb, $top_c, $top_c)
		if $yb < $y + $h
			@d_rect($px, $yb, $pxe, $y + $h, $bot_c, $bot_c)
	; pitch ladder every 10 deg
	var $lad = color(235, 240, 245)
	repeat 13 ($q)
		var $p = ($q - 6) * 10
		if ($p != 0) and (abs($p - $pitch) < 24)
			var $d = ($p - $pitch) * $ppd
			var $lx = $cx - $sr * $d
			var $ly = $cy - $cr * $d
			var $half = $w * 0.12
			@att_line($lx - $cr * $half, $ly + $sr * $half, $lx + $cr * $half, $ly - $sr * $half, $x, $y, $w, $h, $lad)
			if $w >= $cw * 24
				var $pl = text("{}", abs($p))
				@att_text_c($lx + $cr * ($half + $cw * 1.6), $ly - $sr * ($half + $cw * 1.6) - $chh / 2, $lad, $pl, $y, $h)
	; the horizon line, trimmed to the box
	var $hx1 = $x
	var $hx2 = $x + $w
	var $ey1 = $hcy - ($hx1 - $hcx) * $tn
	var $ey2 = $hcy - ($hx2 - $hcx) * $tn
	if ($ey1 >= $y) and ($ey1 <= $y + $h) and ($ey2 >= $y) and ($ey2 <= $y + $h)
		@d_line($hx1, $ey1, $hx2, $ey2, color(250, 250, 250))
	; bank scale (top arc ticks) and pointer
	var $br = min($w, $h) * 0.42
	repeat 9 ($b)
		var $ba = 0
		if $b == 0
			$ba = -60
		elseif $b == 1
			$ba = -45
		elseif $b == 2
			$ba = -30
		elseif $b == 3
			$ba = -20
		elseif $b == 4
			$ba = -10
		elseif $b == 5
			$ba = 10
		elseif $b == 6
			$ba = 20
		elseif $b == 7
			$ba = 30
		else
			$ba = 45
		var $bb = ($ba - 90) * pi / 180
		var $tl = $br * 0.08
		if (abs($ba) == 30) or (abs($ba) == 60)
			$tl = $br * 0.14
		@att_line($cx + cos($bb) * $br, $cy + sin($bb) * $br, $cx + cos($bb) * ($br + $tl), $cy + sin($bb) * ($br + $tl), $x, $y, $w, $h, color(240, 240, 240))
	@att_line($cx, $cy - $br - $br * 0.16, $cx, $cy - $br, $x, $y, $w, $h, color(240, 240, 240))
	var $pa = (-90 - $roll) * pi / 180
	var $pxp = $cx + cos($pa) * ($br - 2)
	var $pyp = $cy + sin($pa) * ($br - 2)
	var $pw = $br * 0.07
	@att_line($pxp, $pyp, $pxp - cos($pa + 1.2) * $pw * 2, $pyp - sin($pa + 1.2) * $pw * 2, $x, $y, $w, $h, color(255, 220, 40))
	@att_line($pxp, $pyp, $pxp - cos($pa - 1.2) * $pw * 2, $pyp - sin($pa - 1.2) * $pw * 2, $x, $y, $w, $h, color(255, 220, 40))
	; aircraft symbol (fixed)
	var $acw = $w * 0.16
	var $acol = color(255, 220, 40)
	var $at = max(1, floor($h / 120))
	@d_thick($cx - $acw * 2, $cy, $cx - $acw * 0.8, $cy, $at, $acol)
	@d_thick($cx - $acw * 0.8, $cy, $cx - $acw * 0.8, $cy + $acw * 0.3, $at, $acol)
	@d_thick($cx + $acw * 0.8, $cy, $cx + $acw * 2, $cy, $at, $acol)
	@d_thick($cx + $acw * 0.8, $cy, $cx + $acw * 0.8, $cy + $acw * 0.3, $at, $acol)
	@d_rect($cx - $at - 1, $cy - $at - 1, $cx + $at + 1, $cy + $at + 1, $acol, $acol)

; Vertical tape (speed on the left, altitude on the right).
function @att_vtape($x : number, $y : number, $w : number, $h : number, $v : number, $tick : number, $label_every : number, $ppu : number, $right : number)
	@ui_box($x, $y, $w, $h, color(16, 22, 30), $th_line)
	var $cy = $y + $h / 2
	var $span = $h / 2 / $ppu
	var $first = floor(($v - $span) / $tick) * $tick
	var $n = min(ceil($span * 2 / $tick) + 2, 80)
	repeat $n ($k)
		var $tv = $first + $k * $tick
		var $ty = $cy - ($tv - $v) * $ppu
		if ($ty > $y + 1) and ($ty < $y + $h - 1)
			var $big = abs(mod($tv, $label_every)) < 0.001
			var $tl = $w * 0.15
			if $big
				$tl = $w * 0.3
			if $right
				@d_line($x, $ty, $x + $tl, $ty, $th_dim)
			else
				@d_line($x + $w - $tl, $ty, $x + $w, $ty, $th_dim)
			if $big and ($ty - $chh / 2 > $y) and ($ty + $chh / 2 < $y + $h)
				var $lt = text("{}", $tv)
				if $right
					@ui_text($x + $tl + $cw * 0.3, $ty - $chh / 2, $th_text, $lt)
				else
					@ui_text_r($x + $w - $tl - $cw * 0.3, $ty - $chh / 2, $th_text, $lt)
	; current value box
	var $vt = text("{0}", $v)
	var $bw = $w
	@ui_box($x, $cy - $chh * 0.8, $bw, $chh * 1.6, $th_bg, $th_text)
	@ui_text_c($x + $bw / 2, $cy - $chh / 2, $th_text, $vt)

; Heading tape across the top.
function @att_htape($x : number, $y : number, $w : number, $h : number, $hdg : number)
	@ui_box($x, $y, $w, $h, color(16, 22, 30), $th_line)
	var $cx = $x + $w / 2
	var $ppd = $w / 70
	var $first = floor(($hdg - 35) / 5) * 5
	repeat 16 ($k)
		var $hv = $first + $k * 5
		var $tx = $cx + ($hv - $hdg) * $ppd
		if ($tx > $x + 1) and ($tx < $x + $w - 1)
			var $hn = @posmod($hv, 360)
			var $big = @posmod($hn, 10) == 0
			var $tl = $h * 0.18
			if $big
				$tl = $h * 0.32
			@d_line($tx, $y + $h - $tl, $tx, $y + $h, $th_dim)
			if @posmod($hn, 30) == 0
				var $lb = text("{}", floor($hn / 10))
				if $hn == 0
					$lb = "N"
				elseif $hn == 90
					$lb = "E"
				elseif $hn == 180
					$lb = "S"
				elseif $hn == 270
					$lb = "W"
				if ($tx - $cw > $x) and ($tx + $cw < $x + $w)
					@ui_text_c($tx, $y + $h * 0.1, $th_text, $lb)
	var $ht = @pad2(floor(@posmod($hdg, 360) / 10)) & text("{}", floor(@posmod($hdg, 10)))
	var $hb = $cw * 5
	@ui_box($cx - $hb / 2, $y, $hb, $h, $th_bg, $th_text)
	@ui_text_c($cx, $y + ($h - $chh) / 2, $th_text, $ht)

function @att_draw_in($x : number, $y : number, $w : number, $h : number)
	$att_live = 1
	@att_find_nav()
	@ui_box($x, $y, $w, $h, $th_panel, $th_line)
	if $att_nav == ""
		@text_fit_c($x + $w / 2, $y + $h / 2 - $chh * 1.2, $th_warn, "NO NAV INSTRUMENT", $w - $cw)
		@text_fit_c($x + $w / 2, $y + $h / 2 + $chh * 0.4, $th_dim, "Name (alias) a Nav Instrument", $w - $cw)
		return
	var $spd = @in_n($att_nav, 0)
	var $vs = @in_n($att_nav, 1)
	var $alt = @in_n($att_nav, 2)
	var $agl = @in_n($att_nav, 3)
	var $pitch = @in_n($att_nav, 4) * 180
	var $roll = @in_n($att_nav, 5) * 180
	var $hdg = @in_n($att_nav, 6)
	; units: metric km/h, m, m/s; imperial kt, ft, ft/min
	var $sv = $spd * 3.6
	var $av = $alt
	var $gv = $agl
	var $vv = $vs
	var $vu = "m/s"
	var $au = "m"
	var $su = "km/h"
	if $cfg_units
		$sv = $spd * 1.94384
		$av = $alt * 3.28084
		$gv = $agl * 3.28084
		$vv = $vs * 196.85
		$vu = "ft/min"
		$au = "ft"
		$su = "kt"
	var $pad = 2
	var $ix = $x + $pad
	var $iy = $y + $pad
	var $iw = $w - $pad * 2
	var $ih = $h - $pad * 2
	var $full = ($iw >= $cw * 30) and ($ih >= $chh * 12)
	if !$full
		; compact: horizon with the three key numbers over it
		@att_horizon($ix, $iy, $iw, $ih, $pitch, $roll)
		var $st = text("{0}", $sv)
		var $at = text("{0}", $av)
		var $htx = text("{0}", @posmod($hdg, 360))
		; dark backing so the numbers stay readable over the ladder
		var $bk = color(4, 6, 10)
		var $stw = size($st) * $cw
		var $atw = size($at) * $cw
		var $htw = size($htx) * $cw
		@ui_box($ix + $cw * 0.4 - 2, $iy + $chh * 0.2 - 1, $stw + 4, $chh + 2, $bk, $bk)
		@ui_box($ix + $iw - $cw * 0.4 - $atw - 2, $iy + $chh * 0.2 - 1, $atw + 4, $chh + 2, $bk, $bk)
		@ui_box($ix + $iw / 2 - $htw / 2 - 2, $iy + $ih - $chh * 1.2 - 1, $htw + 4, $chh + 2, $bk, $th_line)
		@ui_text($ix + $cw * 0.4, $iy + $chh * 0.2, $th_text, $st)
		@ui_text_r($ix + $iw - $cw * 0.4, $iy + $chh * 0.2, $th_text, $at)
		@ui_text_c($ix + $iw / 2, $iy + $ih - $chh * 1.2, $th_text, $htx)
		return
	var $tw = max($cw * 6.5, $iw * 0.13)
	var $th = $chh * 2.2
	var $bot = $chh * 1.6
	var $hx = $ix + $tw
	var $hw = $iw - $tw * 2
	var $hy = $iy + $th
	var $hh = $ih - $th - $bot
	@att_horizon($hx, $hy, $hw, $hh, $pitch, $roll)
	@att_htape($hx, $iy, $hw, $th, $hdg)
	; speed: ticks every 10 (labels every 20), altitude: 20 / 100 (m) or 100 / 500 (ft)
	@att_vtape($ix, $hy, $tw, $hh, $sv, 10, 20, $hh / 120, 0)
	var $atick = 20
	var $alab = 100
	if $cfg_units
		$atick = 100
		$alab = 500
	@att_vtape($ix + $iw - $tw, $hy, $tw, $hh, $av, $atick, $alab, $hh / ($alab * 4), 1)
	@ui_text_c($ix + $tw / 2, $iy + ($th - $chh) / 2, $th_dim, $su)
	@ui_text_c($ix + $iw - $tw / 2, $iy + ($th - $chh) / 2, $th_dim, $au)
	; bottom line: vertical speed and height above ground
	var $vst = text("VS {0.0} ", $vv) & $vu
	if $cfg_units
		$vst = text("VS {0} ", $vv) & $vu
	if $vv > 0
		$vst = text("VS +{0.0} ", $vv) & $vu
		if $cfg_units
			$vst = text("VS +{0} ", $vv) & $vu
	var $gt = text("AGL {0} ", $gv) & $au
	@ui_text($ix + $cw * 0.5, $iy + $ih - $bot + $chh * 0.3, $th_text, $vst)
	@ui_text_r($ix + $iw - $cw * 0.5, $iy + $ih - $bot + $chh * 0.3, $th_text, $gt)

; The whole display in a rectangle; uses a smaller font when the screen's
; font is too big for the tapes to fit.
function @att_draw($x : number, $y : number, $w : number, $h : number)
	var $sv_ts = $ts
	var $sv_cw = $cw
	var $sv_chh = $chh
	repeat 6 ($sk)
		if (($w < $cw * 31) or ($h < $chh * 13)) and ($ts > 1)
			$ts = max(1, $ts - 1)
			$rt.text_size(@tsz($ts))
			$cw = $rt.char_w
			$chh = $rt.char_h
	@att_draw_in($x, $y, $w, $h)
	if $ts != $sv_ts
		$ts = $sv_ts
		$rt.text_size(@tsz($ts))
		$cw = $sv_cw
		$chh = $sv_chh


; ---------------- compass + speedometer / odometer ----------------
storage var $odo_m : number             ; odometer, metres
storage var $trip_m : number            ; trip meter, metres
var $odo_run = 0                        ; running total (saved every 5 s)
var $trip_run = 0
var $odo_ready = 0
var $odo_t = 0
var $odo_save = 0
var $spd_src = ""                       ; speed sensor alias ("" = none)
var $spd_src_next = 0
var $spd_max = 0                        ; highest speed seen (dial range)

function @spd_find()
	if time < $spd_src_next
		return
	$spd_src_next = time + 3
	$spd_src = ""
	var $n = $db_id.size
	repeat $n ($j)
		if ($spd_src == "") and contains($db_type.$j, "SpeedSensor") and ($db_alias.$j != "") and ($db_seen.$j >= $scan_gen - 1)
			$spd_src = $db_alias.$j

; Speed in m/s: the speed sensor, else the nav instrument's ground speed (-1 = none).
function @spd_now() : number
	@spd_find()
	if $spd_src != ""
		return abs(@in_n($spd_src, 0))
	@att_find_nav()
	if $att_nav != ""
		return abs(@in_n($att_nav, 10))
	return -1

; Every tick: add the distance travelled.
function @odo_tick()
	if !$odo_ready
		$odo_ready = 1
		$odo_run = $odo_m
		$trip_run = $trip_m
		$odo_t = time
		return
	var $dt = time - $odo_t
	$odo_t = time
	if ($dt <= 0) or ($dt > 2)
		return
	var $v = @spd_now()
	if $v > 0.2
		$odo_run += $v * $dt
		$trip_run += $v * $dt
		$spd_max = max($spd_max, $v)
	if (time >= $odo_save) and (($odo_m != $odo_run) or ($trip_m != $trip_run))
		$odo_save = time + 5
		$odo_m = $odo_run
		$trip_m = $trip_run

function @odo_trip_reset()
	$trip_run = 0
	$trip_m = 0

; Compass: rose turns so the heading is at the top (lubber line).
function @compass_rose($cx : number, $cy : number, $r : number, $hdg : number, $crs : number, $has_crs : number)
	@d_circle($cx, $cy, $r, $th_line, $th_panel2)
	var $tk = max(1, floor($r / 60))
	repeat 72 ($k)
		var $b = $k * 5
		var $a = ($b - $hdg - 90) * pi / 180
		var $tl = $r * 0.06
		var $col = $th_dim
		if @posmod($b, 30) == 0
			$tl = $r * 0.14
			$col = $th_text
		elseif @posmod($b, 10) == 0
			$tl = $r * 0.1
		var $ca = cos($a)
		var $sa = sin($a)
		@d_line($cx + $ca * ($r - $tl), $cy + $sa * ($r - $tl), $cx + $ca * ($r - 1), $cy + $sa * ($r - 1), $col)
		if (@posmod($b, 30) == 0) and ((@posmod($b, 90) == 0) or ($r >= $chh * 7))
			var $lb = text("{}", floor($b / 10))
			var $lc = $th_text
			if $b == 0
				$lb = "N"
				$lc = $th_bad
			elseif $b == 90
				$lb = "E"
			elseif $b == 180
				$lb = "S"
			elseif $b == 270
				$lb = "W"
			var $lr = $r - $tl - $chh * 0.9
			if $lr > $chh
				@ui_text_c($cx + $ca * $lr, $cy + $sa * $lr - $chh / 2, $lc, $lb)
	; course marker (direction of travel)
	if $has_crs
		var $ac = ($crs - $hdg - 90) * pi / 180
		@d_thick($cx + cos($ac) * $r * 0.55, $cy + sin($ac) * $r * 0.55, $cx + cos($ac) * $r * 0.8, $cy + sin($ac) * $r * 0.8, $tk, $th_ok)
	; lubber line + aircraft / vehicle mark
	var $ly = $cy - $r
	@d_thick($cx, $ly - $r * 0.08, $cx, $ly + $r * 0.16, $tk, color(255, 220, 40))
	@d_line($cx - $r * 0.1, $cy - $r * 0.12, $cx + $r * 0.1, $cy - $r * 0.12, color(255, 220, 40))
	@d_line($cx, $cy - $r * 0.2, $cx, $cy - $r * 0.04, color(255, 220, 40))

function @card_name($h : number) : text
	var $i = @posmod(round($h / 45), 8)
	if $i == 0
		return "N"
	if $i == 1
		return "NE"
	if $i == 2
		return "E"
	if $i == 3
		return "SE"
	if $i == 4
		return "S"
	if $i == 5
		return "SW"
	if $i == 6
		return "W"
	return "NW"

function @compass_draw($x : number, $y : number, $w : number, $h : number)
	$att_live = 1
	@att_find_nav()
	@ui_box($x, $y, $w, $h, $th_panel, $th_line)
	if $att_nav == ""
		@text_fit_c($x + $w / 2, $y + $h / 2 - $chh * 1.2, $th_warn, "NO NAV INSTRUMENT", $w - $cw)
		@text_fit_c($x + $w / 2, $y + $h / 2 + $chh * 0.4, $th_dim, "Name (alias) a Nav Instrument", $w - $cw)
		return
	var $hdg = @posmod(@in_n($att_nav, 6), 360)
	var $crs = @posmod(@in_n($att_nav, 7), 360)
	var $gs = @in_n($att_nav, 10)
	var $has_crs = $gs > 1
	var $ht = @pad2(floor($hdg / 10)) & text("{}", floor(@posmod($hdg, 10)))
	var $hl = $ht & " " & @card_name($hdg)
	if $w > $h * 1.5
		; wide: rose on the left, numbers on the right
		var $r = min($h * 0.44, $w * 0.24)
		var $rcx = $x + $cw + $r + $r * 0.1
		@compass_rose($rcx, $y + $h / 2, $r, $hdg, $crs, $has_crs)
		var $tx0 = $rcx + $r * 1.15 + $cw
		var $tw = $x + $w - $cw - $tx0
		var $tm = @fit_mul(size($hl), $tw, $h * 0.3, 4)
		@ui_text_big($tx0 + $tw / 2, $y + $h / 2 - $chh * $tm, $th_text, $hl, $tm)
		if $has_crs
			var $ct = "COURSE " & @pad2(floor($crs / 10)) & text("{}", floor(@posmod($crs, 10)))
			@text_fit_c($tx0 + $tw / 2, $y + $h / 2 + $chh * 0.4, $th_ok, $ct, $tw)
		return
	var $r2 = max(min($w * 0.46, $h * 0.46), $chh * 2)
	var $ccy = $y + $h / 2
	@compass_rose($x + $w / 2, $ccy, $r2, $hdg, $crs, $has_crs)
	; heading in the middle of the rose
	var $hm = @fit_mul(size($hl), $r2 * 1.0, $r2 * 0.28, 4)
	@ui_text_big($x + $w / 2, $ccy + $r2 * 0.22, $th_text, $hl, $hm)
	if $has_crs and ($r2 > $chh * 6)
		var $ct2 = "CRS " & @pad2(floor($crs / 10)) & text("{}", floor(@posmod($crs, 10)))
		@ui_text_c($x + $w / 2, $ccy + $r2 * 0.22 + $chh * $hm + $chh * 0.2, $th_ok, $ct2)

; Speedometer: 270-degree dial, digital speed, odometer and trip.
function @speedo_draw($x : number, $y : number, $w : number, $h : number)
	$att_live = 1
	@ui_box($x, $y, $w, $h, $th_panel, $th_line)
	var $v = @spd_now()
	if $v < 0
		@text_fit_c($x + $w / 2, $y + $h / 2 - $chh * 1.2, $th_warn, "NO SPEED SOURCE", $w - $cw)
		@text_fit_c($x + $w / 2, $y + $h / 2 + $chh * 0.4, $th_dim, "Name a Speed Sensor or Nav Instrument", $w - $cw)
		return
	; units: km/h + km, or mph + mi
	var $k = 3.6
	var $su = "km/h"
	var $dk = 0.001
	var $du = "km"
	if $cfg_units
		$k = 2.23694
		$su = "mph"
		$dk = 0.000621371
		$du = "mi"
	var $sv = $v * $k
	; dial range: next step above the top speed seen (at least 60 / 40)
	var $top = max($spd_max * $k * 1.1, 60)
	; round full-scale values that split into 8 whole steps
	var $mx = 3200
	repeat 14 ($si)
		var $cand = 3200
		if $si == 0
			$cand = 80
		elseif $si == 1
			$cand = 120
		elseif $si == 2
			$cand = 160
		elseif $si == 3
			$cand = 200
		elseif $si == 4
			$cand = 240
		elseif $si == 5
			$cand = 320
		elseif $si == 6
			$cand = 400
		elseif $si == 7
			$cand = 480
		elseif $si == 8
			$cand = 640
		elseif $si == 9
			$cand = 800
		elseif $si == 10
			$cand = 1200
		elseif $si == 11
			$cand = 1600
		elseif $si == 12
			$cand = 2400
		if ($cand >= $top) and ($cand < $mx)
			$mx = $cand
	var $odo = $odo_run * $dk
	var $trip = $trip_run * $dk
	var $ot = text("{0.0}", @posmod($odo, 1000000))
	var $tt = "TRIP " & text("{0.0} ", $trip) & $du
	var $wide = $w > $h * 1.5
	var $r = max(min($w * 0.44, ($h - $chh * 3.8) / 2), $chh * 2)
	var $cx = $x + $w / 2
	var $cy = $y + $chh * 0.3 + $r
	if $wide
		$r = min($h * 0.44, $w * 0.24)
		$cx = $x + $cw + $r * 1.1
		$cy = $y + $h / 2
	@d_circle($cx, $cy, $r, $th_line, $th_panel2)
	; ticks: 8 major steps
	var $steps = 8
	repeat 33 ($q)
		var $fr = $q / 32
		var $a = (135 + $fr * 270) * pi / 180
		var $major = @posmod($q, 4) == 0
		var $tl = $r * 0.07
		var $col = $th_dim
		if $major
			$tl = $r * 0.15
			$col = $th_text
		@d_line($cx + cos($a) * ($r - $tl), $cy + sin($a) * ($r - $tl), $cx + cos($a) * ($r - 2), $cy + sin($a) * ($r - 2), $col)
		var $every = 4
		if $r < $chh * 8
			$every = 8
		if $major and ($r > $chh * 4) and (@posmod($q, $every) == 0)
			var $lv = text("{}", round($mx * $fr))
			var $lr = $r - $tl - $chh * 1.1
			@ui_text_c($cx + cos($a) * $lr, $cy + sin($a) * $lr - $chh / 2, $th_text, $lv)
	; needle
	var $nf = clamp($sv / $mx, 0, 1.03)
	var $na = (135 + $nf * 270) * pi / 180
	var $nt = max(1, floor($r / 50))
	@d_thick($cx, $cy, $cx + cos($na) * $r * 0.82, $cy + sin($na) * $r * 0.82, $nt, $th_bad)
	@d_circle($cx, $cy, max(2, $r * 0.07), $th_text, $th_text)
	; digital speed under the hub
	var $sd = text("{0}", $sv)
	if $wide
		var $tx0 = $cx + $r * 1.1 + $cw
		var $tw = $x + $w - $cw - $tx0
		var $sm = @fit_mul(size($sd) + 1, $tw, $h * 0.32, 5)
		@ui_text_big($tx0 + $tw / 2, $y + $h * 0.12, $th_text, $sd, $sm)
		@text_fit_c($tx0 + $tw / 2, $y + $h * 0.12 + $chh * $sm + $chh * 0.1, $th_dim, $su, $tw)
		var $odo_y = $y + $h * 0.62
		@ui_box($tx0, $odo_y, $tw, $chh * 1.6, color(4, 6, 10), $th_line)
		@text_fit_c($tx0 + $tw / 2, $odo_y + $chh * 0.3, $th_text, $ot & " " & $du, $tw - $cw)
		@text_fit_c($tx0 + $tw / 2, $odo_y + $chh * 2, $th_dim, $tt, $tw)
		$ui_hv = 0
		@ui_hit($tx0, $odo_y, $tx0 + $tw, $odo_y + $chh * 3.2, "trip_reset")
		return
	var $dm = @fit_mul(size($sd) + 1, $r * 0.9, $r * 0.32, 4)
	@ui_text_big($cx, $cy + $r * 0.28, $th_text, $sd, $dm)
	if $r > $chh * 5
		@ui_text_c($cx, $cy + $r * 0.28 + $chh * $dm, $th_dim, $su)
	; odometer box under the dial (bigger on big screens), trip under it
	var $otx = $ot & " " & $du
	var $om = @fit_mul(size($otx) + 2, $w * 0.6, max($y + $h - ($cy + $r) - $chh * 1.6, $chh) / 1.6, 2.5)
	var $ob_w = min($w - $cw * 2, $cw * $om * (size($otx) + 2))
	var $obh = $chh * $om * 1.4
	var $oby = $cy + $r + $chh * 0.3
	@ui_box($cx - $ob_w / 2, $oby, $ob_w, $obh, color(4, 6, 10), $th_line)
	@ui_text_big($cx, $oby + $chh * $om * 0.2, $th_text, $otx, $om)
	@text_fit_c($cx, $oby + $obh + $chh * 0.15, $th_dim, $tt, $w - $cw)
	$ui_hv = 0
	@ui_hit($x, $oby, $x + $w, $y + $h, "trip_reset")

; ChipOS - POWER page.
array $pl_rows_y : number

var $pw_g24 = 0                  ; history graph: 0 two hours, 1 a day

function @pw_stepper($y : number, $sx : number, $sw : number, $lab : text, $am : text, $ap : text) : number
	var $rb = $chh * 2
	var $rw = $cw * 4
	$y = @bz_fit($y, $rb)
	var $lf = @ui_fit($lab, floor(($sw - $rw * 2 - $cw * 2) / $cw))
	@ui_text($sx, $y + ($rb - $chh) / 2, $th_text, $lf)
	@ui_btn($sx + $sw - $rw * 2 - $cw, $y, $rw, $rb, "-", $am, 0)
	@ui_btn($sx + $sw - $rw, $y, $rw, $rb, "+", $ap, 0)
	return $y + $rb + $chh * 0.4

; Summary block (gauge, flow, history graph, low-battery rule). Returns the
; y below it.
function @pw_summary($sx : number, $sy : number, $sw : number, $compact : number) : number
	var $gh = $chh * 6
	var $y = @bz_fit($sy, $gh)
	@ui_box($sx, $y, $sw, $gh, $th_panel, $th_line)
	var $g_col = $th_ok
	if $pw_pct < $pw_restore
		$g_col = $th_warn
	if $pw_pct < $pw_low
		$g_col = $th_bad
	var $big = "--"
	if $pw_pct >= 0
		$big = text("{0}%", $pw_pct)
	@ui_text($sx + $cw, $y + $chh * 0.6, $g_col, "BATTERIES " & $big)
	var $bar_x = $sx + $cw
	var $bar_w = $sw - $cw * 2
	var $bar_y = $y + $chh * 2
	@ui_box($bar_x, $bar_y, $bar_w, $chh * 0.9, $th_bg, $th_line)
	if $pw_pct > 0
		@ui_box($bar_x, $bar_y, $bar_w * $pw_pct / 100, $chh * 0.9, $g_col, $g_col)
	@pw_status_lines()
	var $fit_n = floor(($sw - $cw * 2) / $cw)
	var $la = @ui_fit($pw_line_a, $fit_n)
	var $lb = @ui_fit($pw_line_b, $fit_n)
	@ui_text($sx + $cw, $y + $chh * 3.3, $th_text, $la)
	@ui_text($sx + $cw, $y + $chh * 4.5, $th_dim, $lb)
	$y += $gh + $chh * 0.5
	if $pw_shed or $pw_shed_low
		$y = @bz_fit($y, $chh * 2)
		var $shed_l = text("LOW-PRIORITY RELAYS OFF UNTIL {}%", $pw_restore2)
		if $pw_shed
			$shed_l = text("LOW BATTERY: LOW + NORMAL RELAYS OFF UNTIL {}%", $pw_restore)
		@ui_box($sx, $y, $sw, $chh * 2, $th_bad_dk, $th_bad)
		var $shed_f = @ui_fit($shed_l, floor(($sw - $cw * 2) / $cw))
		@ui_text($sx + $cw, $y + $chh * 0.5, $th_text, $shed_f)
		$y += $chh * 2.5
	; Generation line
	$y = @bz_fit($y, $chh * 1.6)
	var $gen = "SOLAR " & @fmt_power($pw_solar) & "   USE ~" & @fmt_power($pw_usage)
	if $pp_idx.size > 0
		$gen = $gen & text("   WIND: {} PROPELLER(S)", $pp_idx.size)
	var $cap_t = "STORAGE " & @fmt_energy($pw_cap)
	var $gen_f = @ui_fit($gen, floor($sw / $cw))
	@ui_text($sx, $y, $th_dim, $gen_f)
	$y += $chh * 1.3
	$y = @bz_fit($y, $chh * 1.6)
	@ui_text($sx, $y, $th_dim, $cap_t)
	$y += $chh * 1.8
	; History graph
	if !$compact
		var $hh = $chh * 7
		$y = @bz_fit($y, $hh)
		@ui_box($sx, $y, $sw, $hh, $th_bg, $th_line)
		var $g_lab = "LAST 2 HOURS"
		var $g_bl = "24H"
		if $pw_g24
			$g_lab = "LAST 24 HOURS"
			$g_bl = "2H"
		@ui_text($sx + $cw * 0.5, $y + $chh * 0.3, $th_dim, $g_lab)
		@ui_btn($sx + $sw - $cw * 7, $y + $chh * 0.15, $cw * 6.5, $chh * 1.3, $g_bl, "pw_g24", 0)
		var $gx = $sx + $cw
		var $gw = $sw - $cw * 2
		var $gy = $y + $chh * 1.6
		var $gh2 = $hh - $chh * 2.2
		var $ly = $gy + $gh2 * (1 - $pw_low / 100)
		var $ly2 = $gy + $gh2 * (1 - $pw_low2 / 100)
		@d_line($gx, $ly, $gx + $gw, $ly, $th_bad_dk)
		@d_line($gx, $ly2, $gx + $gw, $ly2, $th_accent_dk)
		var $hn = $pw_hist.size
		if $pw_g24
			$hn = $pw_hist24.size
		if $hn >= 2
			var $hprev_x = 0
			var $hprev_y = 0
			repeat $hn ($hi)
				var $hval = $pw_hist.$hi
				if $pw_g24
					$hval = $pw_hist24.$hi
				var $hx = $gx + $gw * ($hi + 120 - $hn) / 119
				var $hy = $gy + $gh2 * (1 - clamp($hval, 0, 100) / 100)
				if $hi > 0
					@d_line($hprev_x, $hprev_y, $hx, $hy, $th_ok)
				$hprev_x = $hx
				$hprev_y = $hy
		elseif $hn < 2
			var $coll = "COLLECTING (1 SAMPLE A MINUTE)"
			if $pw_g24
				$coll = "COLLECTING (1 SAMPLE EVERY 12 MINUTES)"
			@ui_text_c($sx + $sw / 2, $gy + $gh2 / 2 - $chh / 2, $th_dim, $coll)
		$y += $hh + $chh * 0.5
	; Load-shedding tiers (narrow screens: one line + EDIT)
	if $compact
		var $rb = $chh * 2
		$y = @bz_fit($y, $rb)
		var $ew = $cw * 7
		var $sl = text("SHED: LOW <{}%  NORMAL <{}%", $pw_low2, $pw_low)
		var $slf = @ui_fit($sl, floor(($sw - $ew - $cw) / $cw))
		@ui_text($sx, $y + ($rb - $chh) / 2, $th_text, $slf)
		@ui_btn($sx + $sw - $ew, $y, $ew, $rb, "EDIT", "go:pw_shed", 0)
		return $y + $rb + $chh * 0.6
	$y = @pw_stepper($y, $sx, $sw, text("LOW-PRIORITY OFF BELOW {}%", $pw_low2), "pw_l2-", "pw_l2+")
	$y = @pw_stepper($y, $sx, $sw, text("LOW-PRIORITY BACK ABOVE {}%", $pw_restore2), "pw_r2-", "pw_r2+")
	$y = @pw_stepper($y, $sx, $sw, text("NORMAL OFF BELOW {}%", $pw_low), "pw_low-", "pw_low+")
	$y = @pw_stepper($y, $sx, $sw, text("NORMAL BACK ABOVE {}%", $pw_restore), "pw_rs-", "pw_rs+")
	$y += $chh * 0.2
	return $y

; Row positions down the list area, skipping screen edges.
function @pl_rows($top : number, $bot : number, $rh : number)
	$pl_rows_y.clear()
	var $cur = $top
	repeat 200 ($rk)
		var $fit = @bz_fit($cur, $rh - 2)
		if $fit + $rh - 2 <= $bot
			$pl_rows_y.append($fit)
			$cur = $fit + $rh

function @pw_group_row($g : number, $x : number, $y : number, $w : number, $h : number)
	var $cy = $y + ($h - $chh) / 2 - 1
	var $bw = min($w * 0.13, $cw * 8)
	var $bh = $h - $chh * 0.7
	var $by = $y + $chh * 0.3
	var $bx = $x + $w - $bw * 4 - $cw * 1.5
	var $gn = $gp_name.$g
	var $gc = @gp_count($g)
	var $gl = $gn & text("  ({} DEVICES)", $gc)
	var $glf = @ui_fit($gl, floor(($bx - $x - $cw * 2) / $cw))
	@ui_text($x + $cw, $cy, $th_text, $glf)
	var $gt = "group:" & $gn
	var $on = @tgt_state($gt)
	var $gs_on = 0
	var $gs_off = 1
	if $on
		$gs_on = 3
		$gs_off = 0
	$ui_hv = $g
	@ui_btn($bx, $by, $bw - 2, $bh, "ON", "gp_on", $gs_on)
	$ui_hv = $g
	@ui_btn($bx + $bw, $by, $bw - 2, $bh, "OFF", "gp_off", $gs_off)
	$ui_hv = $g
	@ui_btn($bx + $bw * 2, $by, $bw - 2, $bh, "EDIT", "gp_edit", 0)
	$ui_hv = $g
	@ui_btn($bx + $bw * 3, $by, $bw - 2, $bh, "X", "gp_del", 2)

function @pw_rule_row($i : number, $x : number, $y : number, $w : number, $h : number)
	var $bw = min($w * 0.13, $cw * 8)
	var $bh = $h - $chh * 0.7
	var $by = $y + $chh * 0.3
	var $bx = $x + $w - $bw * 2 - $cw
	var $dsc = @au_desc($i)
	var $ink = $th_text
	if !$au_en.$i
		$ink = $th_dim
	var $df = @ui_fit($dsc, floor(($bx - $x - $cw * 2) / $cw))
	@ui_text($x + $cw, $y + ($h - $chh) / 2 - 1, $ink, $df)
	$ui_hv = $i
	@ui_hit($x, $y, $bx - $cw, $y + $h - 2, "au_edit")
	var $el = "OFF"
	var $es = 0
	if $au_en.$i
		$el = "ON"
		$es = 3
	$ui_hv = $i
	@ui_btn($bx, $by, $bw - 2, $bh, $el, "au_en", $es)
	$ui_hv = $i
	@ui_btn($bx + $bw, $by, $bw - 2, $bh, "X", "au_del", 2)

function @pw_list($lx : number, $ly : number, $lw : number, $lh : number)
	var $tb_h = $chh * 2.2
	var $tb_w = $lw / 5
	repeat 5 ($tk)
		var $tl = "BATT"
		if $tk == 1
			$tl = "GEN"
		elseif $tk == 2
			$tl = "RELAYS"
		elseif $tk == 3
			$tl = "GROUPS"
		elseif $tk == 4
			$tl = "AUTO"
		var $tst = 0
		if $tk == $pw_sub
			$tst = 1
		$ui_hv = $tk
		@ui_btn($lx + $tb_w * $tk, $ly, $tb_w - $cw * 0.4, $tb_h, $tl, "pws", $tst)
	var $top = $ly + $tb_h + $chh * 0.6
	if $pw_sub == 2
		var $ab_w = min($lw / 2, $cw * 16)
		@ui_btn($lx, $top, $ab_w - $cw * 0.5, $tb_h, "ALL ON", "rl_all1", 3)
		@ui_btn($lx + $ab_w, $top, $ab_w - $cw * 0.5, $tb_h, "ALL OFF", "rl_all0", 0)
		$top += $tb_h + $chh * 0.6
	elseif $pw_sub == 3
		@ui_btn($lx, $top, min($lw, $cw * 20), $tb_h, "+ NEW GROUP", "gp_new", 3)
		$top += $tb_h + $chh * 0.6
	elseif $pw_sub == 4
		@ui_btn($lx, $top, min($lw, $cw * 20), $tb_h, "+ NEW RULE", "au_new", 3)
		$top += $tb_h + $chh * 0.6
	elseif $pw_sub == 0
		var $mh = @ui_fit("Tap a battery to make it MAIN (status bar).", floor($lw / $cw))
		@ui_text($lx, $top, $th_dim, $mh)
		$top += $chh * 1.5
	var $sb_w = max($cw * 3, 18)
	var $rw = $lw - $sb_w - $cw
	var $rh = $chh * 2.2
	if $pw_sub >= 2
		$rh = $chh * 2.6
	@pl_rows($top, $ly + $lh, $rh)
	var $vis = max($pl_rows_y.size, 1)
	; Rows for the chosen sub tab: batteries / generation / relays.
	$sc_total = 0
	if $pw_sub == 0
		$sc_total = $pb_idx.size
	elseif $pw_sub == 1
		$sc_total = $ps_idx.size + $pp_idx.size
	elseif $pw_sub == 3
		$sc_total = $gp_name.size
	elseif $pw_sub == 4
		$sc_total = $au_type.size
	else
		$lst.clear()
		var $rn = $db_id.size
		repeat $rn ($rj)
			if ($db_cat.$rj == 2) and (($db_seen.$rj >= $scan_gen - 1))
				$lst.append($rj)
		$sc_total = $lst.size
	$sc_vis = $vis
	@ui_scroll_clamp()
	if $sc_total == 0
		var $none = "NO NAMED BATTERIES"
		if $pw_sub == 1
			$none = "NO NAMED SOLAR PANELS OR PROPELLERS"
		elseif $pw_sub == 2
			$none = "NO RELAYS"
		elseif $pw_sub == 3
			$none = "NO GROUPS YET"
		elseif $pw_sub == 4
			$none = "NO RULES YET"
		@ui_text_c($lx + $rw / 2, $top + $chh, $th_dim, $none)
	var $name_ch = floor($rw * 0.28 / $cw)
	repeat $vis ($r)
		var $li = $sc_pos + $r
		if $li < $sc_total
			var $ry = $pl_rows_y.$r
			@ui_box($lx, $ry, $rw, $rh - 2, $th_panel, $th_line)
			if $pw_sub == 0
				var $bj = $pb_idx.$li
				var $bq = $pb_charge.$li
				var $bnm = $db_alias.$bj
				var $bink = $th_text
				if $li == $pw_main_k
					$bink = $th_accent
				var $bn = @ui_fit($bnm, $name_ch)
				var $b_col = $th_ok
				if $bq * 100 < $pw_restore
					$b_col = $th_warn
				if $bq * 100 < $pw_low
					$b_col = $th_bad
				@ui_text($lx + $cw, $ry + ($rh - $chh) / 2 - 1, $bink, $bn)
				$ui_hv = $li
				@ui_hit($lx, $ry, $lx + $rw, $ry + $rh - 2, "pw_main")
				var $bbx = $lx + $rw * 0.3
				var $bbw = $rw * 0.22
				@ui_box($bbx, $ry + $rh * 0.3, $bbw, $rh * 0.36, $th_bg, $th_line)
				@ui_box($bbx, $ry + $rh * 0.3, $bbw * $bq, $rh * 0.36, $b_col, $b_col)
				var $bv = $pb_volt.$li
				var $bc = $pb_cap.$li
				var $be = @fmt_energy($bc)
				var $bt = text("{0}%  {0}V  {}", $bq * 100, $bv, $be)
				if $li == $pw_main_k
					$bt = "MAIN  " & $bt
				var $bt_room = floor(($lx + $rw - $cw - ($bbx + $bbw + $cw)) / $cw)
				$bt = @ui_fit($bt, $bt_room)
				@ui_text_r($lx + $rw - $cw, $ry + ($rh - $chh) / 2 - 1, $b_col, $bt)
			elseif $pw_sub == 1
				if $li < $ps_idx.size
					var $sj = $ps_idx.$li
					var $sw2 = $ps_w.$li
					var $sn = @ui_fit($db_alias.$sj, $name_ch)
					@ui_text($lx + $cw, $ry + ($rh - $chh) / 2 - 1, $th_text, $sn)
					var $sbx = $lx + $rw * 0.3
					var $sbw = $rw * 0.22
					@ui_box($sbx, $ry + $rh * 0.3, $sbw, $rh * 0.36, $th_bg, $th_line)
					@ui_box($sbx, $ry + $rh * 0.3, $sbw * clamp($sw2 / 2700, 0, 1), $rh * 0.36, $th_warn, $th_warn)
					var $swt = "SOLAR " & @fmt_power($sw2)
					@ui_text_r($lx + $rw - $cw, $ry + ($rh - $chh) / 2 - 1, $th_warn, $swt)
				else
					var $ppi = $li - $ps_idx.size
					var $pj = $pp_idx.$ppi
					var $pn = @ui_fit($db_alias.$pj, $name_ch)
					@ui_text($lx + $cw, $ry + ($rh - $chh) / 2 - 1, $th_text, $pn)
					var $prps = $pp_rps.$ppi
					var $pthr = $pp_thr.$ppi
					var $ptt = text("PROP {0} RPM  {0} N", $prps * 60, $pthr)
					@ui_text_r($lx + $rw - $cw, $ry + ($rh - $chh) / 2 - 1, $th_dim, $ptt)
			elseif $pw_sub == 3
				@pw_group_row($li, $lx, $ry, $rw, $rh)
			elseif $pw_sub == 4
				@pw_rule_row($li, $lx, $ry, $rw, $rh)
			else
				var $rj2 = $lst.$li
				var $ra = $db_alias.$rj2
				var $rname = $ra
				if $ra == ""
					$rname = "(unnamed) relay"
				var $rn_f = @ui_fit($rname, floor($rw * 0.3 / $cw))
				var $r_ink = $th_text
				if $ra == ""
					$r_ink = $th_warn
				@ui_text($lx + $cw, $ry + ($rh - $chh) / 2 - 1, $r_ink, $rn_f)
				if $ra != ""
					var $bw3 = max(min($rw * 0.12, $cw * 9), $cw * 5.6)
					var $bh3 = $rh - $chh * 0.7
					var $pr_w = max($bw3 + $cw, $cw * 7)
					var $by3 = $ry + $chh * 0.3
					var $bx3 = $lx + $rw - $bw3 * 3 - $cw * 10.5 - $cw * 2
					var $on3 = $db_on.$rj2
					var $s_on = 0
					var $s_off = 0
					var $s_free = 0
					if $on3 == 1
						$s_on = 3
					elseif $on3 == 0
						$s_off = 1
					else
						$s_free = 1
					$ui_hv = $rj2
					@ui_btn($bx3, $by3, $bw3 - 2, $bh3, "ON", "rl_on", $s_on)
					$ui_hv = $rj2
					@ui_btn($bx3 + $bw3, $by3, $bw3 - 2, $bh3, "OFF", "rl_off", $s_off)
					$ui_hv = $rj2
					@ui_btn($bx3 + $bw3 * 2, $by3, $bw3 - 2, $bh3, "FREE", "rl_free", $s_free)
					var $pv = $db_ess.$rj2
					var $ess_l = "ESSENTIAL"
					var $ess_s = 1
					if $pv == 1
						$ess_l = "NORMAL"
						$ess_s = 0
					elseif $pv == 0
						$ess_l = "LOW"
						$ess_s = 2
					$ui_hv = $rj2
					@ui_btn($bx3 + $bw3 * 3 + $cw * 0.5, $by3, $cw * 10.5, $bh3, $ess_l, "rl_ess", $ess_s)
				else
					@ui_text_r($lx + $rw - $cw, $ry + ($rh - $chh) / 2 - 1, $th_warn, "NEEDS NAME")
	@ui_scrollbar($lx + $lw - $sb_w, $top, $sb_w, $ly + $lh - $top)

function @page_power()
	var $px = $content_x
	var $py = $content_y
	var $pw = $content_w
	var $ph = $content_h
	if $pw >= $cw * 80
		; Wide: summary left, list right.
		var $lw = $pw * 0.42
		var $sy = @pw_summary($px, $py, $lw, 0)
		@pw_list($px + $lw + $cw * 2, $py, $pw - $lw - $cw * 2, $ph)
	else
		var $sy2 = @pw_summary($px, $py, $pw, 1)
		@pw_list($px, $sy2, $pw, $py + $ph - $sy2)

; ChipOS - draws an external app's screen inside the shell.
; Draw an App Kit frame into a rectangle. $wapp: -1 the open app's screen,
; else a home-screen widget of app $wapp.
array $xw_id : text                     ; widget button ids this frame
array $xw_app : number                  ; ... and their app
function @xf_render($frame : text, $ax : number, $ay : number, $aw : number, $ah : number, $wapp : number)
	if $hit_on and ($wapp < 0) and ($wapp > -10)
		$xb_id.clear()
	; small areas get smaller app text (sizes are whole numbers on screens)
	var $xk = clamp(min($aw, $ah * 1.4) / 300, 0.5, 1)
	; Split the frame at "|" into elements (kept separately from field splits).
	var $rest = $frame
	var $done = 0
	var $bn = 0
	repeat 200 ($ei)
		if $done
			break
		if !$done
			var $p = find($rest, "|")
			var $el = $rest
			if $p < 0
				$done = 1
			else
				$el = substring($rest, 0, $p)
				$rest = substring($rest, $p + 1, size($rest))
			@xf_split($el, "~")
			var $kind = @xf_txt(0)
			if ($kind == "T") or ($kind == "C")
				var $tx = $ax + $aw * @xf_num(1) / 100
				var $ty = $ay + $ah * @xf_num(2) / 100
				var $tsz = max(@xf_num(3), 0.5)
				var $tcol = @xf_color(@xf_txt(4))
				var $tt = @xf_txt(5)
				var $tsn = @tsz(round($ts * $tsz * $xk))
				$rt.text_size($tsn)
				; never wider than the area: step the size down until it fits
				var $tav = $ax + $aw - $tx
				if $kind == "C"
					$tav = min($tx - $ax, $ax + $aw - $tx) * 2
				repeat 10 ($tq)
					if ($tsn > 1) and (size($tt) * $rt.char_w > $tav)
						$tsn -= 1
						$rt.text_size($tsn)
				var $tcw = $rt.char_w
				var $tlx = $tx
				if $kind == "C"
					$tlx = $tx - size($tt) * $tcw / 2
				@d_write($tlx, $ty, $tcol, $tt)
				$rt.text_size(@tsz($ts))
			elseif $kind == "B"
				var $bx = $ax + $aw * @xf_num(1) / 100
				var $by = $ay + $ah * @xf_num(2) / 100
				var $bw = $aw * @xf_num(3) / 100
				var $bh = $ah * @xf_num(4) / 100
				var $bid = @xf_txt(5)
				var $blab = @xf_txt(6)
				if $wapp <= -10
					; built-in app (-10 - id)
					if $hit_on
						$bk_bid.append($bid)
						$bk_bapp.append(-10 - $wapp)
					$ui_hv = $bk_bid.size - 1
					@ui_btn($bx, $by, $bw, $bh, $blab, "bkbtn", 0)
				elseif $wapp < 0
					if $hit_on
						$xb_id.append($bid)
					$ui_hv = $bn
					@ui_btn($bx, $by, $bw, $bh, $blab, "xbtn", 0)
					$bn += 1
				else
					if $hit_on
						$xw_id.append($bid)
						$xw_app.append($wapp)
					$ui_hv = $xw_id.size - 1
					@ui_btn($bx, $by, $bw, $bh, $blab, "xwbtn", 0)
			elseif $kind == "P"
				var $px = $ax + $aw * @xf_num(1) / 100
				var $py = $ay + $ah * @xf_num(2) / 100
				var $pw = $aw * @xf_num(3) / 100
				var $psz = max(@xf_num(4), 0.5)
				var $pcol = @xf_color(@xf_txt(5))
				$rt.text_size(@tsz(round($ts * $psz * $xk)))
				var $save_cw = $cw
				var $save_chh = $chh
				$cw = $rt.char_w
				$chh = $rt.char_h
				var $pend = @ui_para_l($px, $py, $pcol, @xf_txt(6), $pw)
				$cw = $save_cw
				$chh = $save_chh
				$rt.text_size(@tsz($ts))
			elseif $kind == "M"
				; colour grid: x~y~w~h~cols~rows~digits (0 = empty, 1-9 palette)
				var $mx = $ax + $aw * @xf_num(1) / 100
				var $my = $ay + $ah * @xf_num(2) / 100
				var $mw = $aw * @xf_num(3) / 100
				var $mh = $ah * @xf_num(4) / 100
				var $mc = max(@xf_num(5), 1)
				var $mr = max(@xf_num(6), 1)
				var $md = @xf_txt(7)
				var $cs = min($mw / $mc, $mh / $mr)
				var $mx0 = $mx + ($mw - $cs * $mc) / 2
				@ui_box($mx0 - 2, $my - 2, $cs * $mc + 4, $cs * $mr + 4, $th_bg, $th_line)
				var $mn = min(size($md), $mc * $mr)
				repeat $mn ($mi)
					var $dv = find("0123456789", substring($md, $mi, 1))
					if $dv > 0
						var $mcx = $mx0 + mod($mi, $mc) * $cs
						var $mcy = $my + floor($mi / $mc) * $cs
						var $mcol = @grid_color($dv)
						@d_rect($mcx + 1, $mcy + 1, $mcx + $cs - 1, $mcy + $cs - 1, color(10, 12, 16), $mcol)
			elseif $kind == "V"
				@kv_view($ax, $ay, $aw, $ah)
			elseif (size($kind) == 2) and (find($kind, "V") == 0)
				@kv_over($kind)
			elseif $kind == "R"
				var $rcol = @xf_color(@xf_txt(5))
				var $rx = $ax + $aw * @xf_num(1) / 100
				var $ry = $ay + $ah * @xf_num(2) / 100
				@ui_box($rx, $ry, $aw * @xf_num(3) / 100, $ah * @xf_num(4) / 100, $rcol, $rcol)
			elseif $kind == "G"
				var $gx = $ax + $aw * @xf_num(1) / 100
				var $gy = $ay + $ah * @xf_num(2) / 100
				var $gw = $aw * @xf_num(3) / 100
				var $gh = $ah * @xf_num(4) / 100
				var $gp = clamp(@xf_num(5), 0, 100)
				var $gcol = @xf_color(@xf_txt(6))
				@ui_box($gx, $gy, $gw, $gh, $th_bg, $th_line)
				@ui_box($gx, $gy, $gw * $gp / 100, $gh, $gcol, $gcol)

function @page_xapp()
	var $ax = $content_x
	var $ay = $content_y
	var $aw = $content_w
	var $ah = $content_h
	if ($xa_cur < 0) or ($xa_cur >= $xa_alias.size)
		@ui_text_c($ax + $aw / 2, $ay + $ah / 2, $th_dim, "NO APP")
		return
	var $al = $xa_alias.$xa_cur
	if !$xa_online.$xa_cur
		@ui_text_big($ax + $aw / 2, $ay + $ah * 0.35, $th_bad, "APP OFFLINE", 2)
		var $off_l = "'" & $al & "' is not on the data network or not running."
		var $off_y = @ui_para_c($ax + $aw / 2, $ay + $ah * 0.55, $th_dim, $off_l, $aw * 0.9)
		return
	var $frame = @in_t($al, 1)
	$xa_frame_seen = $frame
	if $frame == ""
		var $wl = "WAITING FOR " & $xa_name.$xa_cur & "..."
		@ui_text_c($ax + $aw / 2, $ay + $ah / 2, $th_dim, $wl)
		return
	@xf_render($frame, $ax, $ay, $aw, $ah, -1)

; ChipOS - built-in Clock app (world clock) and the clock widget builder.
var $ckn_style = 3
var $ckn_zone = -1
var $ckn_dst = 0

; "+3h", "-5h 30m", "same time"
function @fmt_diff($m : number) : text
	if $m == 0
		return "same time"
	var $sg = "+"
	if $m < 0
		$sg = "-"
	var $a = abs($m)
	var $hh = floor($a / 60)
	var $rm = $a - $hh * 60
	var $t = $sg & text("{}h", $hh)
	if $rm > 0
		$t = $t & text(" {}m", $rm)
	return $t

function @page_clock()
	var $x0 = $content_x
	var $y0 = $content_y
	var $W = $content_w
	var $H = $content_h
	; Home zone: analog face + digital time, date, zone.
	var $r = max(min($H * 0.2, $W * 0.18), $chh * 2)
	if ($disp_mode == 1) and ($grp_h > 0)
		; keep the face on one screen of the wall
		$r = max(min($r, ($grp_h - $y0 - $chh * 0.6) / 2, ($grp_w - $x0 - $cw) / 2), $chh * 2)
	@clk_calc(-1, 0)
	var $home_off = $ck_off
	var $home_days = $ck_days
	@clock_face($x0 + $r + $cw * 0.5, $y0 + $r + $chh * 0.3, $r)
	var $tx = $x0 + $r * 2 + $cw * 3
	var $tw = $x0 + $W - $tx
	var $tt = @fmt_hm($ck_h, $ck_mi, $cfg_24h)
	var $ss = ":" & @pad2($ck_s)
	var $tm = @fit_mul(size($tt) + 3, $tw, $r * 0.8, 5)
	var $tcx = $tx + $cw * (size($tt) + 3) * $tm / 2
	@ui_text_big($tcx, $y0 + $r * 0.25, $th_text, $tt & $ss, $tm)
	var $ty = $y0 + $r * 0.25 + $chh * $tm + $chh * 0.6
	var $fd = @fmt_date(4)
	var $fdf = @ui_fit($fd, floor($tw / $cw))
	@ui_text($tx, $ty, $th_dim, $fdf)
	var $zl = @tz_name($cfg_zone) & "   " & @fmt_utc($ck_off)
	if $ck_dst
		$zl = $zl & "  DST"
	var $zlf = @ui_fit($zl, floor($tw / $cw))
	@ui_text($tx, $ty + $chh * 1.5, $th_accent, $zlf)
	if $sun_ok > 0
		var $sl = @ui_fit(@sun_line(), floor($tw / $cw))
		@ui_text($tx, $ty + $chh * 3, $th_dim, $sl)
	; World clock list.
	var $ly = @bz_fit($y0 + $r * 2 + $chh * 1.6, $chh * 2.4)
	var $bw = $cw * 14
	@ui_text($x0, $ly + $chh * 0.6, $th_accent, "WORLD CLOCK")
	@ui_btn($x0 + min($W, $cw * 70) - $bw, $ly, $bw, $chh * 2.2, "+ ADD CITY", "wc_add", 3)
	$ly += $chh * 3
	var $n = $wc_zone.size
	if $n == 0
		var $ey = @ui_para_l($x0, $ly, $th_dim, "Add cities to see their time next to yours.", min($W, $cw * 60))
		return
	var $sb_w = max($cw * 3, 18)
	var $rw = min($W - $sb_w - $cw, $cw * 70)
	var $rh = $chh * 2.6
	var $bot = $y0 + $H
	@pl_rows($ly, $bot, $rh)
	$sc_total = $n
	$sc_vis = max($pl_rows_y.size, 1)
	@ui_scroll_clamp()
	var $xb = $chh * 2.2
	repeat $sc_vis ($k)
		var $li = $sc_pos + $k
		if $li < $n
			var $ry = $pl_rows_y.$k
			var $z = $wc_zone.$li
			@clk_calc($z, 0)
			@ui_box($x0, $ry, $rw, $rh - 2, $th_panel, $th_line)
			var $cy = $ry + ($rh - 2 - $chh) / 2
			var $nm = @tz_short($z)
			if $ck_dst
				$nm = $nm & " (DST)"
			@ui_text($x0 + $cw, $cy, $th_text, $nm)
			var $zt = @fmt_hm($ck_h, $ck_mi, $cfg_24h)
			var $tx2 = $x0 + $rw - $xb - $cw
			@ui_text_r($tx2, $cy, $th_text, $zt)
			var $df = @fmt_diff($ck_off - $home_off)
			if $ck_days > $home_days
				$df = $df & ", TOMORROW"
			elseif $ck_days < $home_days
				$df = $df & ", YESTERDAY"
			var $mx = $x0 + $cw * max(18, size($nm) + 3)
			if $tx2 - size($zt) * $cw - $cw > $mx + size($df) * $cw
				@ui_text($mx, $cy, $th_dim, $df)
			$ui_hv = $li
			@ui_btn($x0 + $rw - $xb - 2, $ry + ($rh - 2 - $xb) / 2, $xb, $xb, "X", "wc_del", 2)
	@ui_scrollbar($x0 + $rw + $cw, $ly, $sb_w, $bot - $ly)

