; ChipOS v0.1 - core: identity, theme, helpers, device categories.
const $os_name = "ChipOS"
const $os_version = "v0.29.5"

var $th_bg = color(6, 10, 16)
var $th_panel = color(13, 21, 31)
var $th_panel2 = color(20, 33, 47)
var $th_line = color(38, 62, 84)
var $th_text = color(222, 232, 240)
var $th_dim = color(118, 138, 158)
var $th_accent = color(0, 196, 228)
var $th_accent_dk = color(0, 70, 92)
var $th_ok = color(46, 200, 96)
var $th_ok_dk = color(14, 64, 32)
var $th_warn = color(240, 170, 34)
var $th_bad = color(220, 64, 60)
var $th_bad_dk = color(76, 20, 22)

function @os_log($line : text)
	print("ChipOS: " & $line)

function @pad2($n : number) : text
	if $n < 10
		return text("0{}", $n)
	return text("{}", $n)

var $boot_t = -1
function @uptime_text() : text
	if $boot_t < 0
		$boot_t = time
	var $u_s = floor(time - $boot_t)
	var $u_h = floor($u_s / 3600)
	var $u_m = floor(mod($u_s, 3600) / 60)
	var $u_sec = mod($u_s, 60)
	var $u_mm = @pad2($u_m)
	var $u_ss = @pad2($u_sec)
	return text("{}:{}:{}", $u_h, $u_mm, $u_ss)

; ---- Device categories (from the component's type name) ----
; 0 other, 1 light, 2 power switch, 3 battery, 4 comms, 5 screen,
; 6 network/infrastructure, 7 fluid, 8 storage, 9 machine, 10 joint,
; 11 propulsion, 12 sensor, 13 solar, 14 computer, 15 control
const $cat_count = 16

function @cat_of($t : text) : number
	if contains($t, "Relay")
		return 2
	var $lt = lower($t)
	if contains($lt, "lamp") or contains($lt, "light")
		return 1
	if contains($t, "Battery")
		return 3
	if contains($t, "Beacon") or contains($t, "Antenna")
		return 4
	if contains($t, "Dashboard") or contains($t, "Hud") or contains($t, "Screen")
		return 5
	if contains($t, "Computer")
		return 14
	if contains($t, "Router") or contains($t, "Junction") or contains($t, "Bridge") or contains($t, "Converter") or contains($t, "Conveyor")
		return 6
	if contains($t, "SolarPanel")
		return 13
	if contains($t, "Sensor") or contains($t, "Nav") or contains($t, "Scanner") or contains($t, "Probe")
		return 12
	if contains($t, "Tank") or contains($t, "Pump") or contains($t, "Valve") or contains($t, "Radiator") or contains($t, "FluidPort") or contains($t, "Volume")
		return 7
	if contains($t, "Container") or contains($t, "TrashCan")
		return 8
	if contains($t, "Crafter") or contains($t, "Furnace") or contains($t, "Centrifuge") or contains($t, "Electrolyser") or contains($t, "Sabatier") or contains($t, "Crusher") or contains($t, "Drill") or contains($t, "Generator") or contains($t, "Reactor") or contains($t, "RTG") or contains($t, "Turbine") or contains($t, "Geothermal")
		return 9
	if contains($t, "Pivot") or contains($t, "Hinge") or contains($t, "LinearTrack")
		return 10
	if contains($t, "Propeller") or contains($t, "Thruster") or contains($t, "Wheel") or contains($t, "Turbojet") or contains($t, "RCS") or contains($t, "Aileron")
		return 11
	if contains($t, "Keyboard") or contains($t, "Numpad") or contains($t, "Seat") or contains($t, "Button") or contains($t, "Lever") or contains($t, "Pad")
		return 15
	return 0

function @cat_name($c : number) : text
	if $c == 1
		return "LIGHT"
	if $c == 2
		return "POWER SWITCH"
	if $c == 3
		return "BATTERY"
	if $c == 4
		return "COMMS"
	if $c == 5
		return "SCREEN"
	if $c == 6
		return "NETWORK"
	if $c == 7
		return "FLUID"
	if $c == 8
		return "STORAGE"
	if $c == 9
		return "MACHINE"
	if $c == 10
		return "JOINT"
	if $c == 11
		return "PROPULSION"
	if $c == 12
		return "SENSOR"
	if $c == 13
		return "SOLAR"
	if $c == 14
		return "COMPUTER"
	if $c == 15
		return "CONTROL"
	return "OTHER"

; Alias prefix suggested for an unnamed device ("" = needs no name).
function @cat_prefix($c : number) : text
	if $c == 1
		return "light"
	if $c == 2
		return "relay"
	if $c == 3
		return "battery"
	if $c == 4
		return "beacon"
	if $c == 5
		return "screen"
	if ($c == 6) or ($c == 14)
		return ""
	if $c == 7
		return "fluid"
	if $c == 8
		return "container"
	if $c == 9
		return "machine"
	if $c == 10
		return "joint"
	if $c == 11
		return "prop"
	if $c == 12
		return "sensor"
	if $c == 13
		return "solar"
