function @cat_color($c : number) : number
	if $c == 1
		return color(250, 214, 90)
	if $c == 2
		return color(240, 140, 40)
	if $c == 3
		return color(70, 210, 110)
	if $c == 4
		return color(170, 120, 250)
	if $c == 5
		return color(0, 196, 228)
	if $c == 6
		return color(90, 110, 130)
	if $c == 7
		return color(60, 140, 250)
	if $c == 8
		return color(190, 150, 100)
	if $c == 9
		return color(230, 90, 70)
	if $c == 10
		return color(150, 200, 220)
	if $c == 11
		return color(250, 110, 190)
	if $c == 12
		return color(120, 230, 210)
	if $c == 13
		return color(255, 190, 40)
	if $c == 14
		return color(160, 170, 180)
	if $c == 15
		return color(200, 200, 120)
	return color(140, 140, 150)

; Text size the screen really draws: whole sizes only, at least 1.
function @tsz($n : number) : number
	return max(1, floor($n + 0.001))

; ---- device addresses: an alias, or "#N" for a device plugged straight into
; port N of this computer (no alias needed; see db scan) ----
function @io_port($a : text) : number
	if find($a, "#") != 0
		return -1
	var $p = 0
	$p = substring($a, 1, 4)
	return $p

function @in_n($a : text, $c : number) : number
	var $p = @io_port($a)
	if $p >= 0
		return input_number($p, $c)
	return input_number($a, $c)

function @in_t($a : text, $c : number) : text
	var $p = @io_port($a)
	if $p >= 0
		return input_text($p, $c)
	return input_text($a, $c)

function @out_n($a : text, $c : number, $v : number)
	var $p = @io_port($a)
	if $p >= 0
		output_number($p, $c, $v)
	else
		output_number($a, $c, $v)

function @out_t($a : text, $c : number, $v : text)
	var $p = @io_port($a)
	if $p >= 0
		output_text($p, $c, $v)
	else
		output_text($a, $c, $v)

; HELLO WORLD - a ChipOS app. Alias this computer "app-hello".
include "chipos-appkit.xc"
var $taps = 0

init
	@kit_app("HELLO", "#ff8800", "H")

update
	@kit_poll()
	if $kit_tap == "tap"
		$taps += 1
	if $kit_tap == "reset"
		$taps = 0
	if @kit_should_draw()
		@kit_begin()
		@kit_text_c(50, 8, 3, "accent", "HELLO WORLD")
		@kit_text_c(50, 28, 1.2, "dim", "This screen comes from a second computer.")
		var $tl = text("Taps: {}", $taps)
		@kit_text_c(50, 40, 2, "text", $tl)
		@kit_bar(20, 52, 60, 6, mod($taps, 10) * 10, "ok")
		@kit_button("tap", 20, 64, 28, 14, "TAP ME")
		@kit_button("reset", 52, 64, 28, 14, "RESET")
		var $cl = "ChipOS time " & $kit_clock & "   day " & text("{}", $kit_day)
		@kit_text_c(50, 88, 1, "dim", $cl)
		@kit_end()
